script:
/* ==========================================================================
   مركز القوائم المالية الشاملة — Custom HTML Block (ERPNext v15 / v16)
   كل القوائم بتتحسب هنا: المرحّل + أثر القيود المسودة، من غير ما نروح لتقارير السيستم.
   يتلزق في خانة "Script" في الـ Custom HTML Block.
   ========================================================================== */
(function () {
  "use strict";

  // ============================================================ إعدادات
  const ACCENT = "#0E5E6F";                    // اللون الثاني (نفس أول سطر في CSS)
  const CUSTOM_GL = "Custom General Ledger";   // تقرير الأستاذ المخصص اللي بيجيب المسودات
  const DRAFT_KEYS = ["include_draft_entries", "include_draft", "include_drafts", "show_draft_entries", "draft_entries"];
  // المستندات المسودة اللي بنحسب أثرها. ضيف أي نوع تاني بيعمل قيود عندكم.
  const DRAFT_DOCTYPES = [
    { dt: "Journal Entry", label: "قيد يومية", title: "title", amount: "total_debit" },
    { dt: "Sales Invoice", label: "فاتورة مبيعات", title: "customer", amount: "grand_total" },
    { dt: "Purchase Invoice", label: "فاتورة مشتريات", title: "supplier", amount: "grand_total" },
    { dt: "Payment Entry", label: "سند قبض / صرف", title: "party", amount: "paid_amount" },
  ];
  const PARTY_TYPES = ["Customer", "Supplier", "Employee", "Shareholder"];
  const PARTY_AR = { Customer: "العملاء", Supplier: "الموردين", Employee: "الموظفين", Shareholder: "المساهمين" };
  const PARTY_ONE = { Customer: "عميل", Supplier: "مورد", Employee: "موظف", Shareholder: "مساهم" };

  // ============================================================ أدوات
  const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
  const n2 = (v) => format_number(flt(v), null, 2);
  const fmt = (v) => { v = flt(v, 2); if (!v) return '<span class="z">—</span>'; return v < 0 ? `(${n2(-v)})` : n2(v); };
  const udate = (d) => (d ? frappe.datetime.str_to_user(d) : "");
  const split = (v) => [v > 0 ? v : 0, v < 0 ? -v : 0];
  const td = (v, cls) => `<td class="n ${cls || ""}" data-v="${flt(v, 2)}">${fmt(v)}</td>`;
  const balTd = (v, cls) => {
    v = flt(v, 2);
    return `<td class="n ${cls || ""}" data-v="${v}">${v ? `${n2(Math.abs(v))} <small>${v > 0 ? "مدين" : "دائن"}</small>` : '<span class="z">—</span>'}</td>`;
  };
  const draftFlags = (on) => DRAFT_KEYS.reduce((o, k) => ((o[k] = on ? 1 : 0), o), {});
  const isSummaryRow = (r) => { const a = String((r && (r.account || r.party)) || ""); return a.startsWith("'") || a.startsWith('"'); };
  const isDraftRow = (r) => r.docstatus === 0 || r.docstatus === "0" || cint(r.is_draft) === 1 || cint(r.draft) === 1 || cint(r.is_draft_entry) === 1;

  function fiscalYear(date) {
    try {
      const r = erpnext.utils.get_fiscal_year(date, true);
      if (Array.isArray(r)) return { name: r[0], start: r[1], end: r[2] };
      if (r) return { name: r };
    } catch (e) { /* ignore */ }
    const y = (date || frappe.datetime.get_today()).slice(0, 4);
    return { name: y, start: `${y}-01-01`, end: `${y}-12-31` };
  }

  async function runReport(report_name, filters) {
    const r = await frappe.call({ method: "frappe.desk.query_report.run", args: { report_name, filters, ignore_prepared_report: 1 } });
    const m = r.message || {};
    if (m.prepared_report && !m.result) throw new Error(`تقرير "${report_name}" مضبوط Prepared Report — لازم يتشغّل مباشر.`);
    return m;
  }

  async function pool(items, size, fn) {
    let i = 0;
    const worker = async () => { while (i < items.length) { const it = items[i++]; try { await fn(it); } catch (e) { console.error(e); } } };
    await Promise.all(Array.from({ length: Math.min(size, items.length) }, worker));
  }

  // ============================================================ Excel حقيقي (.xlsx) من غير مكتبات
  const XLSX = (() => {
    const T = new Uint32Array(256);
    for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; T[n] = c >>> 0; }
    const crc32 = (u) => { let c = 0xffffffff; for (let i = 0; i < u.length; i++) c = T[(c ^ u[i]) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
    const enc = new TextEncoder();
    function zip(files) {
      const parts = [], central = [];
      let off = 0;
      files.forEach((f) => {
        const name = enc.encode(f.name), data = enc.encode(f.data), crc = crc32(data);
        const lh = new DataView(new ArrayBuffer(30));
        lh.setUint32(0, 0x04034b50, true); lh.setUint16(4, 20, true); lh.setUint16(6, 0x0800, true); lh.setUint16(12, 0x21, true);
        lh.setUint32(14, crc, true); lh.setUint32(18, data.length, true); lh.setUint32(22, data.length, true); lh.setUint16(26, name.length, true);
        parts.push(new Uint8Array(lh.buffer), name, data);
        const ch = new DataView(new ArrayBuffer(46));
        ch.setUint32(0, 0x02014b50, true); ch.setUint16(4, 20, true); ch.setUint16(6, 20, true); ch.setUint16(8, 0x0800, true); ch.setUint16(14, 0x21, true);
        ch.setUint32(16, crc, true); ch.setUint32(20, data.length, true); ch.setUint32(24, data.length, true); ch.setUint16(28, name.length, true); ch.setUint32(42, off, true);
        central.push(new Uint8Array(ch.buffer), name);
        off += 30 + name.length + data.length;
      });
      const cs = central.reduce((s, a) => s + a.length, 0);
      const end = new DataView(new ArrayBuffer(22));
      end.setUint32(0, 0x06054b50, true); end.setUint16(8, files.length, true); end.setUint16(10, files.length, true); end.setUint32(12, cs, true); end.setUint32(16, off, true);
      return new Blob([...parts, ...central, new Uint8Array(end.buffer)], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    }
    const x = (s) => String(s == null ? "" : s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
    const col = (i) => { let s = ""; i++; while (i) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
    const A = ACCENT.replace("#", "FF").toUpperCase();
    // الأنماط: 0 عادي، 1 رقم، 2 نص عريض، 3 رقم عريض، 4 رأس/إجمالي، 5 قسم (لون التمييز)، 6 رقم قسم، 7 عنوان، 8 رمادي، 9 رقم مسودة، 10 رقم إجمالي
    const STYLES = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
<numFmts count="1"><numFmt numFmtId="164" formatCode="#,##0.00;(#,##0.00);&quot;-&quot;"/></numFmts>
<fonts count="6"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><color rgb="FFFFFFFF"/><name val="Calibri"/></font><font><b/><sz val="15"/><color rgb="${A}"/><name val="Calibri"/></font><font><sz val="10"/><color rgb="FF7C7C7C"/><name val="Calibri"/></font><font><i/><sz val="11"/><color rgb="${A}"/><name val="Calibri"/></font></fonts>
<fills count="4"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFF3F3F3"/></patternFill></fill><fill><patternFill patternType="solid"><fgColor rgb="${A}"/></patternFill></fill></fills>
<borders count="2"><border/><border><top style="medium"><color rgb="${A}"/></top></border></borders>
<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
<cellXfs count="11">
<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>
<xf numFmtId="164" fontId="0" fillId="0" borderId="0" applyNumberFormat="1" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="0" borderId="0" applyFont="1" xfId="0"/>
<xf numFmtId="164" fontId="1" fillId="0" borderId="0" applyNumberFormat="1" applyFont="1" xfId="0"/>
<xf numFmtId="0" fontId="1" fillId="2" borderId="1" applyFont="1" applyFill="1" applyBorder="1" xfId="0"/>
<xf numFmtId="0" fontId="2" fillId="3" borderId="0" applyFont="1" applyFill="1" xfId="0"/>
<xf numFmtId="164" fontId="2" fillId="3" borderId="0" applyNumberFormat="1" applyFont="1" applyFill="1" xfId="0"/>
<xf numFmtId="0" fontId="3" fillId="0" borderId="0" applyFont="1" xfId="0"/>
<xf numFmtId="0" fontId="4" fillId="0" borderId="0" applyFont="1" xfId="0"/>
<xf numFmtId="164" fontId="5" fillId="0" borderId="0" applyNumberFormat="1" applyFont="1" xfId="0"/>
<xf numFmtId="164" fontId="1" fillId="2" borderId="1" applyNumberFormat="1" applyFont="1" applyFill="1" applyBorder="1" xfId="0"/>
</cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;
    // rows: [[{v, n:boolean, s:styleIndex}]]
    function build(sheetName, rows) {
      const widths = [];
      const sd = rows.map((r, ri) => `<row r="${ri + 1}">${r.map((c, ci) => {
        if (!c || (c.v === "" && !c.s)) return "";
        const ref = col(ci) + (ri + 1);
        widths[ci] = Math.max(widths[ci] || 8, Math.min(60, String(c.n ? n2(c.v) : c.v).length + 2));
        return c.n
          ? `<c r="${ref}" s="${c.s || 1}"><v>${Number(c.v) || 0}</v></c>`
          : `<c r="${ref}" s="${c.s || 0}" t="inlineStr"><is><t xml:space="preserve">${x(c.v)}</t></is></c>`;
      }).join("")}</row>`).join("");
      const cols = widths.length ? `<cols>${widths.map((w, i) => `<col min="${i + 1}" max="${i + 1}" width="${w || 10}" customWidth="1"/>`).join("")}</cols>` : "";
      const name = String(sheetName).replace(/[\[\]:*?\/\\]/g, " ").slice(0, 31) || "Sheet1";
      return zip([
        { name: "[Content_Types].xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/></Types>` },
        { name: "_rels/.rels", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>` },
        { name: "xl/workbook.xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><bookViews><workbookView/></bookViews><sheets><sheet name="${x(name)}" sheetId="1" r:id="rId1"/></sheets></workbook>` },
        { name: "xl/_rels/workbook.xml.rels", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>` },
        { name: "xl/styles.xml", data: STYLES },
        { name: "xl/worksheets/sheet1.xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0" rightToLeft="1" showGridLines="0"/></sheetViews>${cols}<sheetData>${sd}</sheetData></worksheet>` },
      ]);
    }
    function download(filename, sheetName, rows) {
      const a = document.createElement("a");
      a.href = URL.createObjectURL(build(sheetName, rows));
      a.download = filename.endsWith(".xlsx") ? filename : filename + ".xlsx";
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 3000);
    }
    return { build, download };
  })();

  // ============================================================ CSS للعرض والطباعة
  const VIEW_CSS = `
  .fv{--a:${ACCENT};--g0:var(--card-bg,#fff);--g1:var(--gray-50,#F8F8F8);--g2:var(--gray-100,#F3F3F3);--g3:var(--gray-200,#EDEDED);--g4:var(--gray-300,#E2E2E2);--g5:var(--gray-500,#999);--g6:var(--gray-600,#7C7C7C);--g7:var(--gray-700,#525252);--g9:var(--gray-900,#171717);direction:rtl;color:var(--text-color,#171717);font-family:inherit}
  .fv *{box-sizing:border-box}
  .fv-tabs{display:flex;gap:2px;overflow-x:auto;border-bottom:1px solid var(--g4);margin-bottom:16px}
  .fv-tabs button{font:inherit;font-size:13px;background:none;border:0;border-bottom:2px solid transparent;padding:10px 14px;color:var(--g6);cursor:pointer;white-space:nowrap;margin-bottom:-1px}
  .fv-tabs button:hover{color:var(--g9)}
  .fv-tabs button.on{color:var(--a);border-bottom-color:var(--a);font-weight:700}
  .fv-bar{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:14px}
  .fv-k{font-size:11px;color:var(--a);font-weight:700;letter-spacing:.3px}
  .fv-bar h3{margin:2px 0 3px;font-size:18px;font-weight:700;color:var(--g9)}
  .fv-meta{font-size:12px;color:var(--g6)}
  .fv-tools{display:flex;gap:6px;align-items:center;flex-wrap:wrap}
  .fv-tools select,.fv-tools input{height:32px;border:1px solid var(--g4);border-radius:8px;background:var(--g0);color:var(--g9);padding:0 10px;font:inherit;font-size:12px}
  .fv-tools input{width:170px}
  .fv-btn{height:32px;font:inherit;font-size:12px;border-radius:8px;padding:0 12px;cursor:pointer;border:1px solid var(--g4);background:var(--g0);color:var(--g9)}
  .fv-btn:hover{border-color:var(--a);color:var(--a)}
  .fv-btn.p{background:var(--a);border-color:var(--a);color:#fff}
  .fv-hide{display:none!important}
  .fv-load{padding:48px 10px;text-align:center;color:var(--g6);font-size:13px}
  .fv-pb{height:6px;background:var(--g2);border-radius:6px;overflow:hidden;max-width:420px;margin:0 auto 12px}
  .fv-pb i{display:block;height:100%;width:0;background:var(--a);transition:width .25s}
  .fv-err{padding:24px;border:1px dashed var(--g4);border-radius:12px;text-align:center;color:var(--g7);font-size:13px;line-height:1.8}
  .fv-sum{display:grid;grid-template-columns:repeat(auto-fit,minmax(165px,1fr));gap:10px;margin-bottom:14px}
  .fv-c{background:var(--g2);border:0;border-radius:12px;padding:12px 14px;display:flex;flex-direction:column;gap:3px;text-align:right;font:inherit;color:inherit;min-height:78px}
  .fv-c span{font-size:11px;color:var(--g6)}
  .fv-c b{font-size:18px;font-variant-numeric:tabular-nums;direction:ltr;text-align:right;color:var(--g9)}
  .fv-c small{font-size:11px;color:var(--a);font-weight:600}
  .fv-c.a{background:var(--a)}.fv-c.a b{color:#fff}.fv-c.a span,.fv-c.a small{color:rgba(255,255,255,.85)}
  button.fv-c{cursor:pointer;transition:transform .15s,box-shadow .15s}
  button.fv-c:hover{transform:translateY(-2px);box-shadow:0 6px 16px -10px rgba(0,0,0,.35)}
  .fv-tw{border:1px solid var(--g4);border-radius:12px;overflow:auto;max-height:68vh;background:var(--g0)}
  .fv-t{width:100%;border-collapse:collapse;font-size:12.5px}
  .fv-t thead th{position:sticky;top:0;z-index:1;background:var(--g2);font-weight:600;color:var(--g7);text-align:right;padding:9px 12px;border-bottom:1px solid var(--g4);white-space:nowrap}
  .fv-t td{padding:7px 12px;border-bottom:1px solid var(--g3);vertical-align:top}
  .fv-t .n{text-align:left;direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap}
  .fv-t .n small{font-size:10px;color:var(--g6)}
  .fv-t td.a,.fv-t th.a{background:color-mix(in srgb,var(--a) 6%,transparent);color:var(--a)}
  .fv-t td.s{font-weight:600}
  .fv-t .z{color:var(--g4)}
  .fv-t tr.g td{font-weight:600}
  .fv-t tr.g.d0 td{background:var(--g1);font-weight:700}
  .fv-t tr[data-g] td.nm{cursor:pointer;user-select:none}
  .fv-t .cr{display:inline-block;font-style:normal;color:var(--g5);margin-inline-end:6px;transition:transform .15s;font-size:10px}
  .fv-t tr.col .cr{transform:rotate(90deg)}
  .fv-t tr.lk td.nm{cursor:pointer}
  .fv-t tr.lk:hover td.nm{color:var(--a);text-decoration:underline}
  .fv-t tr.sec td{background:var(--a);color:#fff;font-weight:700;font-size:13px;padding:9px 12px}
  .fv-t tr.tot td{background:var(--g2);font-weight:700;border-top:2px solid var(--a)}
  .fv-t tr.tot td.a{background:var(--g2)}
  .fv-t tr.grand td{background:var(--a);color:#fff;font-weight:700;font-size:13px}
  .fv-t tr.grand td small,.fv-t tr.grand .z{color:rgba(255,255,255,.8)}
  .fv-t tr.ln td{font-style:italic;color:var(--g7)}
  .fv-t tr.dr td{color:var(--a);font-style:italic}
  .fv-t tr.hid{display:none}
  .fv-t tbody tr[data-s]:hover td{background:var(--g1)}
  .fv-t tbody tr[data-s]:hover td.a{background:color-mix(in srgb,var(--a) 10%,transparent)}
  .fv-t .pc{color:var(--g6);font-size:11px}
  .fv-t .sub{display:block;font-size:11px;color:var(--g6);font-weight:400}
  .tag{display:inline-block;font-size:10px;padding:1px 7px;border-radius:8px;background:var(--a);color:#fff;margin-inline-start:6px;font-style:normal;font-weight:600;vertical-align:middle}
  .tag.g{background:var(--g3);color:var(--g7)}
  .fv-note{font-size:11px;color:var(--g6);margin-top:10px;line-height:1.8}
  .fv-grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:4px}
  .fv-panel{border:1px solid var(--g4);border-radius:12px;padding:14px 16px;background:var(--g0)}
  .fv-panel h4{margin:0 0 4px;font-size:13px;font-weight:700}
  .fv-panel .lg{font-size:11px;color:var(--g6);margin-bottom:12px;display:flex;gap:12px}
  .fv-panel .lg i{display:inline-block;width:10px;height:10px;border-radius:3px;background:var(--g5);margin-inline-end:4px;vertical-align:-1px}
  .fv-panel .lg i.d{background:var(--a)}
  .bar{display:grid;grid-template-columns:minmax(100px,36%) 1fr minmax(80px,auto);gap:10px;align-items:center;font-size:12px;margin-bottom:9px}
  .bar .l{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--g7)}
  .bar .tr{height:10px;background:var(--g2);border-radius:6px;overflow:hidden;display:flex}
  .bar .tr i{display:block;height:100%;background:var(--g5)}
  .bar .tr i.d{background:var(--a)}
  .bar .v{text-align:left;direction:ltr;font-variant-numeric:tabular-nums;color:var(--g9)}
  .chips{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}
  .chips button{border:1px solid var(--g4);background:var(--g0);color:var(--g7);font:inherit;font-size:12px;padding:5px 12px;border-radius:20px;cursor:pointer}
  .chips button:hover{border-color:var(--a);color:var(--a)}
  .chips button.on{background:var(--a);border-color:var(--a);color:#fff}
  .st{border:1px solid var(--g4);border-radius:12px;overflow:hidden;margin-bottom:18px;background:var(--g0)}
  .st-head{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:14px 16px;background:var(--g2);border-bottom:3px solid var(--a)}
  .st-head h3{margin:2px 0;font-size:16px}
  .st-chips{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
  .st-chip{background:var(--g0);border-radius:8px;padding:6px 10px;min-width:110px}
  .st-chip span{display:block;font-size:10px;color:var(--g6)}
  .st-chip b{font-size:13px;font-variant-numeric:tabular-nums}
  .st-chip.a{background:var(--a);color:#fff}.st-chip.a span{color:rgba(255,255,255,.8)}
  .st .fv-t thead th{position:static}
  .st-index{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:14px}
  .st-index a{font-size:12px;padding:4px 10px;border-radius:14px;background:var(--g2);color:var(--g7);text-decoration:none;cursor:pointer}
  .st-index a:hover{background:var(--a);color:#fff}
  .fv-empty{padding:34px;text-align:center;color:var(--g6);font-size:13px}
  @media(max-width:820px){.fv-grid2{grid-template-columns:1fr}}
  `;
  const PRINT_CSS = `
  @page{size:A4;margin:11mm}
  body{font-family:"Segoe UI",Tahoma,Arial,sans-serif;margin:0;padding:12px;-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .no-print,.st-index{display:none!important}
  .fv-tw{max-height:none;overflow:visible;border:0;border-radius:0}
  .fv-t thead th{position:static}
  thead{display:table-header-group} tr{break-inside:avoid}
  .st{break-before:page;border-radius:0}.st:first-of-type{break-before:auto}
  .fv-grid2{grid-template-columns:1fr 1fr}
  .ph{display:flex;justify-content:space-between;align-items:flex-end;border-bottom:3px solid ${ACCENT};padding-bottom:8px;margin-bottom:14px}
  .ph h1{font-size:18px;margin:0}.ph .k{font-size:11px;color:${ACCENT};font-weight:700}.ph div{font-size:11px;color:#7C7C7C}
  `;
  function injectCss(target, id) {
    if (target === document.head) {
      if (document.getElementById(id)) return;
      const s = document.createElement("style"); s.id = id; s.textContent = VIEW_CSS; document.head.appendChild(s);
    } else if (!target.querySelector(`style[data-id="${id}"]`)) {
      const s = document.createElement("style"); s.dataset.id = id; s.textContent = VIEW_CSS; target.appendChild(s);
    }
  }
  injectCss(document.head, "fh-view-css-v2");

  // ============================================================ المحرّك: أرصدة شاملة لكل حساب
  // b = { po: افتتاحي مرحّل، pdr/pcr: حركة مرحّلة، dop: افتتاحي مسودات، ddr/dcr: حركة مسودات }
  const ZERO = Object.freeze({ po: 0, pdr: 0, pcr: 0, dop: 0, ddr: 0, dcr: 0 });
  const KEYS = Object.keys(ZERO);
  const CL = (b, p) => (p === "p" ? b.po + b.pdr - b.pcr : b.dop + b.ddr - b.dcr);   // رصيد ختامي
  const MV = (b, p) => (p === "p" ? b.pdr - b.pcr : b.ddr - b.dcr);                  // حركة الفترة
  const ALL = (fn) => (b) => fn(b, "p") + fn(b, "d");

  const modelCache = {};
  function ctxKey(ctx) { return [ctx.company, ctx.from, ctx.to, ctx.drafts ? 1 : 0].join("|"); }
  function getModel(ctx, progress) {
    const k = ctxKey(ctx);
    if (!modelCache[k]) modelCache[k] = buildModel(ctx, progress).catch((e) => { delete modelCache[k]; throw e; });
    return modelCache[k];
  }
  function clearCache() { Object.keys(modelCache).forEach((k) => delete modelCache[k]); }

  const pickGl = (r) => ({ account: r.account, debit: flt(r.debit), credit: flt(r.credit), party_type: r.party_type || "", party: r.party || "" });
  async function draftGl(ctx, d) {
    // 1) نفس منطق الديفلوبر: تقرير الأستاذ المخصص على المستند ده بس
    try {
      const res = await runReport(CUSTOM_GL, { company: ctx.company, from_date: d.date, to_date: d.date, voucher_no: d.name, ...draftFlags(true) });
      const rows = (res.result || []).filter((r) => r && !Array.isArray(r) && !isSummaryRow(r) && r.account && r.voucher_no === d.name);
      if (rows.length) { d.source = "gl"; return rows.map(pickGl); }
    } catch (e) { /* fallback */ }
    // 2) معاينة القيود اللي في ERPNext نفسه للمستندات المسودة
    try {
      const r = await frappe.call({ method: "erpnext.controllers.stock_controller.show_accounting_ledger_preview", args: { company: ctx.company, doctype: d.dt, docname: d.name } });
      const m = r.message || {};
      const cols = (m.gl_columns || []).map((c) => c.fieldname);
      const rows = (m.gl_data || []).map((row) => (Array.isArray(row) ? Object.fromEntries(cols.map((c, i) => [c, row[i]])) : row)).filter((x) => x && x.account);
      if (rows.length) { d.source = "preview"; return rows.map(pickGl); }
    } catch (e) { /* ignore */ }
    d.failed = true;
    return [];
  }

  async function buildModel(ctx, progress) {
    progress = progress || (() => {});
    const fy = fiscalYear(ctx.from);
    if (fy.start && ctx.from < fy.start) throw new Error("تاريخ البداية قبل بداية السنة المالية.");
    if (fy.end && ctx.to > fy.end) throw new Error(`الفترة لازم تكون داخل سنة مالية واحدة (${fy.name}: ${udate(fy.start)} ← ${udate(fy.end)}).`);

    progress(5, "تحميل شجرة الحسابات");
    const accs = await frappe.db.get_list("Account", {
      filters: { company: ctx.company },
      fields: ["name", "account_name", "account_number", "parent_account", "is_group", "root_type", "report_type", "account_type", "lft"],
      order_by: "lft asc",
      limit: 100000,
    });
    const meta = {}, children = {}, roots = [];
    accs.forEach((a) => (meta[a.name] = a));
    accs.forEach((a) => {
      if (a.parent_account && meta[a.parent_account]) (children[a.parent_account] = children[a.parent_account] || []).push(a.name);
      else roots.push(a.name);
    });

    progress(15, "الأرصدة المرحّلة");
    const tb = await runReport("Trial Balance", {
      company: ctx.company, fiscal_year: fy.name, from_date: ctx.from, to_date: ctx.to,
      show_zero_values: 0, with_period_closing_entry_for_opening: 1, with_period_closing_entry_for_current_period: 0, include_default_book_entries: 1,
    });
    const bal = {};
    const B = (n) => bal[n] || (bal[n] = { po: 0, pdr: 0, pcr: 0, dop: 0, ddr: 0, dcr: 0 });
    (tb.result || []).forEach((r) => {
      if (!r || !r.account || isSummaryRow(r) || !meta[r.account] || cint(meta[r.account].is_group)) return;
      const b = B(r.account);
      b.po = flt(r.opening_debit) - flt(r.opening_credit);
      b.pdr = flt(r.debit);
      b.pcr = flt(r.credit);
    });

    let drafts = [], priorPL = 0;
    if (ctx.drafts) {
      progress(25, "حصر المستندات المسودة");
      const lists = await Promise.all(DRAFT_DOCTYPES.map(async (d) => {
        try {
          const fields = ["name", "posting_date", d.title, d.amount].filter(Boolean);
          const rows = await frappe.db.get_list(d.dt, { filters: { company: ctx.company, docstatus: 0, posting_date: ["<=", ctx.to] }, fields, order_by: "posting_date asc", limit: 5000 });
          return rows.map((r) => ({ dt: d.dt, label: d.label, name: r.name, date: r.posting_date, title: r[d.title] || "", amount: flt(r[d.amount]), gl: [] }));
        } catch (e) { return []; }
      }));
      drafts = lists.flat().filter((d) => d.date);
      let done = 0;
      await pool(drafts, 6, async (d) => {
        d.gl = await draftGl(ctx, d);
        done++;
        progress(25 + Math.round((65 * done) / drafts.length), `تحليل قيود المسودات ${done} / ${drafts.length}`);
      });
      drafts.forEach((d) => {
        d.inPeriod = d.date >= ctx.from;
        d.gl.forEach((g) => {
          const m = meta[g.account];
          if (!m) return;
          if (!d.inPeriod) {
            if (m.report_type === "Profit and Loss" && fy.start && d.date < fy.start) { priorPL += g.debit - g.credit; return; }
            B(g.account).dop += g.debit - g.credit;
          } else {
            const b = B(g.account); b.ddr += g.debit; b.dcr += g.credit;
          }
        });
      });
    }

    progress(95, "تجميع الشجرة");
    for (let i = accs.length - 1; i >= 0; i--) {            // من الأوراق للجذور
      const n = accs[i].name, p = accs[i].parent_account;
      if (p && meta[p] && bal[n]) { const pb = B(p), b = bal[n]; KEYS.forEach((k) => (pb[k] += b[k])); }
    }
    const leaves = accs.filter((a) => !cint(a.is_group)).map((a) => a.name);
    progress(100, "تم");
    return {
      ctx, fy, meta, children, roots, bal, leaves, drafts, priorPL, party: {},
      get: (n) => bal[n] || ZERO,
      rootsBy: (rt) => roots.filter((r) => meta[r].root_type === rt),
      leavesBy: (pred) => leaves.filter((n) => pred(meta[n])),
    };
  }

  // ============================================================ بناء الجداول
  const accLabel = (m) => (m ? (m.account_number && !String(m.account_name).startsWith(m.account_number) ? `${m.account_number} - ${m.account_name}` : m.account_name || m.name) : "");

  function amtCols(model, fn, totalLabel) {
    return model.ctx.drafts
      ? [{ l: "مرحّل", p: "p", f: (b) => fn(b, "p") }, { l: "مسودات", p: "d", a: 1, f: (b) => fn(b, "d") }, { l: totalLabel || "الإجمالي", p: "t", s: 1, f: ALL(fn) }]
      : [{ l: totalLabel || "المبلغ", p: "p", s: 1, f: (b) => fn(b, "p") }];
  }
  const head = (first, cols, extra) =>
    `<thead><tr><th>${first}</th>${cols.map((c) => `<th class="n${c.a ? " a" : ""}">${c.l}</th>`).join("")}${extra || ""}</tr></thead>`;
  const sec = (t, n) => `<tr class="sec"><td colspan="${n}">${t}</td></tr>`;
  const line = (label, vals, cols, cls, extra) =>
    `<tr class="${cls || "tot"}"><td>${label}</td>${vals.map((v, i) => td(v, (cols[i] && cols[i].a ? "a " : "") + (cols[i] && cols[i].s ? "s" : ""))).join("")}${extra || ""}</tr>`;

  // صفوف شجرية؛ valsFn(b) => [] ، الحسابات الصفرية بالكامل بتتخفي
  function tree(model, rootNames, valsFn, cols, opts) {
    opts = opts || {};
    let html = "";
    const walk = (n, d) => {
      const vals = valsFn(model.get(n));
      if (vals.every((v) => Math.abs(v) < 0.005)) return;
      const m = model.meta[n], g = cint(m.is_group);
      const pct = opts.pctBase ? `<td class="n pc">${format_number((100 * vals[vals.length - 1]) / opts.pctBase, null, 1)}%</td>` : "";
      html += `<tr class="${g ? "g" : "lk"} d${Math.min(d, 5)}" data-d="${d}" ${g ? 'data-g="1"' : `data-acc="${esc(n)}"`} data-s="${esc(accLabel(m).toLowerCase())}">
        <td class="nm" style="padding-inline-start:${12 + d * 18}px">${g ? '<i class="cr">▼</i>' : ""}${esc(accLabel(m))}</td>
        ${vals.map((v, i) => (opts.bal && opts.bal[i] ? balTd(v, cols[i] && cols[i].a ? "a" : "") : td(v, (cols[i] && cols[i].a ? "a " : "") + (cols[i] && cols[i].s ? "s" : "")))).join("")}${pct}</tr>`;
      (model.children[n] || []).forEach((c) => walk(c, d + 1));
    };
    rootNames.forEach((r) => walk(r, 0));
    const totals = rootNames.reduce((acc, r) => valsFn(model.get(r)).map((v, i) => (acc[i] || 0) + v), []);
    return { html, totals: totals.length ? totals : (cols || []).map(() => 0) };
  }

  // ============================================================ القوائم
  const VIEWS = {};

  // ---------- نظرة عامة
  VIEWS.overview = {
    label: "نظرة عامة", k: "ملخص تنفيذي", t: "نظرة عامة على الفترة",
    run(model) {
      const sumRoots = (rt, fn, sign) => model.rootsBy(rt).reduce((s, r) => s + sign * fn(model.get(r)), 0);
      const sumLeaves = (types, fn, sign) => model.leavesBy((m) => types.includes(m.account_type)).reduce((s, n) => s + sign * fn(model.get(n)), 0);
      const both = (calc) => ({ t: calc(ALL(MV)), d: calc((b) => MV(b, "d")) });
      const bothCl = (calc) => ({ t: calc(ALL(CL)), d: calc((b) => CL(b, "d")) });
      const rev = both((f) => sumRoots("Income", f, -1));
      const exp = both((f) => sumRoots("Expense", f, 1));
      const np = { t: rev.t - exp.t, d: rev.d - exp.d };
      const assets = bothCl((f) => sumRoots("Asset", f, 1));
      const cash = bothCl((f) => sumLeaves(["Cash", "Bank"], f, 1));
      const ar = bothCl((f) => sumLeaves(["Receivable"], f, 1));
      const ap = bothCl((f) => sumLeaves(["Payable"], f, -1));
      const dCount = model.drafts.length, dIn = model.drafts.filter((d) => d.inPeriod).length;
      const card = (label, o, go, a) =>
        `<button class="fv-c ${a ? "a" : ""}" data-goto="${go}"><span>${label}</span><b>${fmt(o.t)}</b>${model.ctx.drafts ? `<small>${Math.abs(o.d) > 0.005 ? `منها مسودات ${fmt(o.d)}` : "بدون أثر مسودات"}</small>` : ""}</button>`;
      const margin = rev.t ? format_number((100 * np.t) / rev.t, null, 1) + "%" : "—";

      // أعمدة بيانية: مرحّل (رمادي) + مسودات (اللون الثاني)
      const bars = (items, title) => {
        const max = Math.max(1, ...items.map((x) => Math.max(0, x.p) + Math.max(0, x.d)));
        return `<div class="fv-panel"><h4>${title}</h4><div class="lg"><span><i></i>مرحّل</span>${model.ctx.drafts ? '<span><i class="d"></i>مسودات</span>' : ""}</div>
          ${items.length ? items.map((x) => `<div class="bar" title="${esc(x.l)}"><span class="l">${esc(x.l)}</span>
            <span class="tr"><i style="width:${(100 * Math.max(0, x.p)) / max}%"></i><i class="d" style="width:${(100 * Math.max(0, x.d)) / max}%"></i></span>
            <span class="v">${n2(x.p + x.d)}</span></div>`).join("") : '<div class="fv-empty">لا توجد بيانات</div>'}</div>`;
      };
      const top = (names, fn) => names.map((n) => ({ l: accLabel(model.meta[n]), p: fn(model.get(n), "p"), d: fn(model.get(n), "d") }))
        .filter((x) => x.p + x.d > 0.005).sort((a, b) => b.p + b.d - (a.p + a.d)).slice(0, 7);
      const assetItems = top(model.rootsBy("Asset").flatMap((r) => model.children[r] || [r]), CL);
      const expItems = top(model.leavesBy((m) => m.root_type === "Expense"), MV);

      return `<div class="fv-sum">
          ${card("الإيرادات", rev, "pl")}${card("المصروفات", exp, "pl")}${card(`صافي الربح · هامش ${margin}`, np, "pl", true)}${card("إجمالي الأصول", assets, "bs")}
          ${card("النقدية والبنوك", cash, "cash")}${card("ذمم العملاء", ar, "party")}${card("ذمم الموردين", ap, "party")}
          ${model.ctx.drafts ? `<button class="fv-c a" data-goto="drafts"><span>المستندات المسودة</span><b>${dCount}</b><small>${dIn} داخل الفترة · ${dCount - dIn} قبلها</small></button>` : ""}
        </div>
        <div class="fv-grid2">${bars(assetItems, "هيكل الأصول")}${bars(expItems, "أكبر بنود المصروفات في الفترة")}</div>`;
    },
  };

  // ---------- قائمة المركز المالي
  VIEWS.bs = {
    label: "المركز المالي", k: "قائمة", t: "قائمة المركز المالي (الميزانية العمومية)", tree: true,
    run(model) {
      const cols = amtCols(model, CL, "الرصيد");
      const vf = (sign) => (b) => cols.map((c) => sign * c.f(b));
      const A = tree(model, model.rootsBy("Asset"), vf(1), cols);
      const L = tree(model, model.rootsBy("Liability"), vf(-1), cols);
      const E = tree(model, model.rootsBy("Equity"), vf(-1), cols);
      const plRoots = model.roots.filter((r) => ["Income", "Expense"].includes(model.meta[r].root_type));
      const profit = cols.map((c) => -plRoots.reduce((s, r) => s + c.f(model.get(r)), 0));
      const prior = cols.map((c) => (c.p === "p" ? 0 : -model.priorPL));
      const diff = cols.map((c, i) => A.totals[i] - L.totals[i] - E.totals[i] - profit[i] - prior[i]);
      const hasDiff = diff.some((v) => Math.abs(v) > 0.01), hasPrior = prior.some((v) => Math.abs(v) > 0.01);
      const eqTot = cols.map((c, i) => E.totals[i] + profit[i] + prior[i] + (hasDiff ? diff[i] : 0));
      const le = cols.map((c, i) => L.totals[i] + eqTot[i]);
      const n = cols.length + 1, last = cols.length - 1;
      const ok = Math.abs(A.totals[last] - le[last]) < 0.01;

      return `<div class="fv-sum">
          <div class="fv-c"><span>إجمالي الأصول</span><b>${fmt(A.totals[last])}</b></div>
          <div class="fv-c"><span>إجمالي الخصوم</span><b>${fmt(L.totals[last])}</b></div>
          <div class="fv-c"><span>حقوق الملكية (شامل ربح الفترة)</span><b>${fmt(eqTot[last])}</b></div>
          <div class="fv-c a"><span>التوازن</span><b>${ok ? "متوازنة ✓" : "غير متوازنة"}</b><small>الأصول = الخصوم + حقوق الملكية</small></div>
        </div>
        <div class="fv-tw"><table class="fv-t">${head("البند", cols)}<tbody>
          ${sec("الأصول", n)}${A.html}${line("إجمالي الأصول", A.totals, cols)}
          ${sec("الخصوم", n)}${L.html}${line("إجمالي الخصوم", L.totals, cols)}
          ${sec("حقوق الملكية", n)}${E.html}
          ${line("صافي ربح (خسارة) السنة حتى تاريخه", profit, cols, "ln")}
          ${hasPrior ? line("أثر مسودات سنوات مالية سابقة", prior, cols, "ln") : ""}
          ${hasDiff ? line("أرباح (خسائر) مرحّلة غير مقفلة", diff, cols, "ln") : ""}
          ${line("إجمالي حقوق الملكية", eqTot, cols)}
          ${line("إجمالي الخصوم وحقوق الملكية", le, cols, "grand")}
        </tbody></table></div>
        <div class="fv-note">صافي الربح من أول السنة المالية (${esc(model.fy.name)}) حتى ${udate(model.ctx.to)}. ${hasDiff ? "بند «أرباح مرحّلة غير مقفلة» = نتيجة سنوات سابقة لم يُعمل لها قيد إقفال (Period Closing Voucher)." : ""} اضغط على أي حساب لفتح كشفه.</div>`;
    },
  };

  // ---------- قائمة الدخل
  VIEWS.pl = {
    label: "قائمة الدخل", k: "قائمة", t: "قائمة الدخل (الأرباح والخسائر)", tree: true,
    run(model) {
      const cols = amtCols(model, MV, "الإجمالي");
      const vf = (sign) => (b) => cols.map((c) => sign * c.f(b));
      const last = cols.length - 1;
      const base = model.rootsBy("Income").reduce((s, r) => s - cols[last].f(model.get(r)), 0);
      const I = tree(model, model.rootsBy("Income"), vf(-1), cols, { pctBase: base });
      const X = tree(model, model.rootsBy("Expense"), vf(1), cols, { pctBase: base });
      const np = cols.map((c, i) => I.totals[i] - X.totals[i]);
      const cogsLeaves = model.leavesBy((m) => m.account_type === "Cost of Goods Sold");
      const cogs = cols.map((c) => cogsLeaves.reduce((s, nn) => s + c.f(model.get(nn)), 0));
      const gp = cols.map((c, i) => I.totals[i] - cogs[i]);
      const pc = (v) => `<td class="n pc">${base ? format_number((100 * v) / base, null, 1) + "%" : ""}</td>`;
      const n = cols.length + 2;
      const chip = (l, v, a, sub) => `<div class="fv-c ${a ? "a" : ""}"><span>${l}</span><b>${fmt(v)}</b>${sub ? `<small>${sub}</small>` : ""}</div>`;
      const dNote = (v) => (model.ctx.drafts ? `منها مسودات ${fmt(v)}` : "");

      return `<div class="fv-sum">
          ${chip("الإيرادات", I.totals[last], 0, dNote(I.totals[1]))}
          ${Math.abs(cogs[last]) > 0.005 ? chip("تكلفة المبيعات", cogs[last]) + chip("مجمل الربح", gp[last], 0, base ? `هامش ${format_number((100 * gp[last]) / base, null, 1)}%` : "") : ""}
          ${chip("المصروفات", X.totals[last], 0, dNote(X.totals[1]))}
          ${chip("صافي الربح / (الخسارة)", np[last], 1, base ? `هامش صافي ${format_number((100 * np[last]) / base, null, 1)}%` : "")}
        </div>
        <div class="fv-tw"><table class="fv-t">${head("البند", cols, '<th class="n">% من الإيراد</th>')}<tbody>
          ${sec("الإيرادات", n)}${I.html}${line("إجمالي الإيرادات", I.totals, cols, "tot", pc(I.totals[last]))}
          ${sec("المصروفات", n)}${X.html}${line("إجمالي المصروفات", X.totals, cols, "tot", pc(X.totals[last]))}
          ${line("صافي الربح / (الخسارة)", np, cols, "grand", pc(np[last]))}
        </tbody></table></div>
        <div class="fv-note">حركة الفترة من ${udate(model.ctx.from)} إلى ${udate(model.ctx.to)} فقط. الأرقام بين قوسين بالسالب.</div>`;
    },
  };

  // ---------- ميزان المراجعة الشامل
  VIEWS.tb = {
    label: "ميزان المراجعة", k: "ميزان", t: "ميزان المراجعة الشامل", tree: true,
    run(model) {
      const D = model.ctx.drafts;
      const vals = (b) => {
        const o = b.po + b.dop, dr = b.pdr + b.ddr, cr = b.pcr + b.dcr, c = o + dr - cr;
        return [...split(o), dr, cr, ...split(c), ...(D ? [CL(b, "d")] : [])];
      };
      const cols = [{ l: "افتتاحي مدين" }, { l: "افتتاحي دائن" }, { l: "حركة مدين" }, { l: "حركة دائن" }, { l: "ختامي مدين", s: 1 }, { l: "ختامي دائن", s: 1 }, ...(D ? [{ l: "منها مسودات", a: 1 }] : [])];
      const T = tree(model, model.roots, vals, cols, { bal: cols.map((c, i) => i === 6) });
      const tot = model.leaves.reduce((acc, nn) => vals(model.get(nn)).map((v, i) => (acc[i] || 0) + v), cols.map(() => 0));
      const pp = split(model.priorPL);
      if (Math.abs(model.priorPL) > 0.005) { tot[0] += pp[0]; tot[1] += pp[1]; tot[4] += pp[0]; tot[5] += pp[1]; }
      const okO = Math.abs(tot[0] - tot[1]) < 0.01, okM = Math.abs(tot[2] - tot[3]) < 0.01, okC = Math.abs(tot[4] - tot[5]) < 0.01;
      const touched = model.leaves.filter((nn) => { const b = model.get(nn); return Math.abs(b.ddr) + Math.abs(b.dcr) + Math.abs(b.dop) > 0.005; }).length;

      return `<div class="fv-sum">
          <div class="fv-c"><span>الأرصدة الافتتاحية</span><b>${n2(tot[0])}</b><small>${okO ? "متوازنة ✓" : "فرق " + n2(tot[0] - tot[1])}</small></div>
          <div class="fv-c"><span>حركة الفترة</span><b>${n2(tot[2])}</b><small>${okM ? "متوازنة ✓" : "فرق " + n2(tot[2] - tot[3])}</small></div>
          <div class="fv-c"><span>الأرصدة الختامية</span><b>${n2(tot[4])}</b><small>${okC ? "متوازنة ✓" : "فرق " + n2(tot[4] - tot[5])}</small></div>
          ${D ? `<div class="fv-c a"><span>حسابات متأثرة بالمسودات</span><b>${touched}</b><small>${model.drafts.length} مستند مسودة</small></div>` : ""}
        </div>
        <div class="fv-tw"><table class="fv-t">${head("الحساب", cols)}<tbody>${T.html}
          ${Math.abs(model.priorPL) > 0.005 ? `<tr class="ln"><td>أثر مسودات سنوات مالية سابقة</td>${td(pp[0])}${td(pp[1])}${td(0)}${td(0)}${td(pp[0])}${td(pp[1])}${D ? balTd(model.priorPL, "a") : ""}</tr>` : ""}
          ${line("الإجمالي", tot.map((v, i) => (i === 6 ? 0 : v)), cols, "grand")}
        </tbody></table></div>
        <div class="fv-note">الحركة مدين/دائن إجمالية (مرحّل + مسودات). المسودات اللي تاريخها قبل بداية الفترة داخلة في الرصيد الافتتاحي. اضغط على أي حساب لفتح كشفه.</div>`;
    },
  };

  // ---------- موازين الأطراف
  VIEWS.party = {
    label: "موازين الأطراف", k: "ميزان", t: "موازين الأطراف", search: true,
    async run(model, V) {
      const pt = V.party;
      if (!model.party[pt]) {
        model.party[pt] = runReport("Trial Balance for Party", { company: model.ctx.company, fiscal_year: model.fy.name, from_date: model.ctx.from, to_date: model.ctx.to, party_type: pt })
          .catch((e) => { delete model.party[pt]; throw e; });
      }
      const res = await model.party[pt];
      const map = {};
      const P = (p, label) => map[p] || (map[p] = { p, label: label || p, po: 0, pdr: 0, pcr: 0, dop: 0, ddr: 0, dcr: 0 });
      (res.result || []).forEach((r) => {
        if (!r || !r.party || isSummaryRow(r)) return;
        const x = P(r.party, r.party_name);
        x.po = flt(r.opening_debit) - flt(r.opening_credit); x.pdr = flt(r.debit); x.pcr = flt(r.credit);
      });
      model.drafts.forEach((d) => d.gl.forEach((g) => {
        if (g.party_type !== pt || !g.party) return;
        const x = P(g.party);
        if (d.inPeriod) { x.ddr += g.debit; x.dcr += g.credit; } else x.dop += g.debit - g.credit;
      }));
      const rows = Object.values(map).map((x) => {
        const o = x.po + x.dop, dr = x.pdr + x.ddr, cr = x.pcr + x.dcr;
        return { ...x, o, dr, cr, c: o + dr - cr, dn: x.dop + x.ddr - x.dcr };
      }).filter((x) => [x.o, x.dr, x.cr, x.c].some((v) => Math.abs(v) > 0.005)).sort((a, b) => Math.abs(b.c) - Math.abs(a.c));
      const T = rows.reduce((t, x) => ({ o: t.o + x.o, dr: t.dr + x.dr, cr: t.cr + x.cr, c: t.c + x.c, dn: t.dn + x.dn }), { o: 0, dr: 0, cr: 0, c: 0, dn: 0 });
      const D = model.ctx.drafts;
      const debtors = rows.filter((x) => x.c > 0.005).length, creditors = rows.filter((x) => x.c < -0.005).length;

      return `<div class="chips no-print">${PARTY_TYPES.map((p) => `<button data-pt="${p}" class="${p === pt ? "on" : ""}">${PARTY_AR[p]}</button>`).join("")}</div>
        <div class="fv-sum">
          <div class="fv-c"><span>عدد ${PARTY_AR[pt]} بأرصدة أو حركة</span><b>${rows.length}</b></div>
          <div class="fv-c"><span>أرصدة مدينة</span><b>${debtors}</b></div>
          <div class="fv-c"><span>أرصدة دائنة</span><b>${creditors}</b></div>
          <div class="fv-c a"><span>صافي الرصيد الختامي</span><b>${n2(Math.abs(T.c))} ${T.c >= 0 ? "مدين" : "دائن"}</b>${D ? `<small>منها مسودات ${fmt(T.dn)}</small>` : ""}</div>
        </div>
        <div class="fv-tw"><table class="fv-t"><thead><tr><th>${PARTY_ONE[pt]}</th><th class="n">رصيد أول المدة</th><th class="n">مدين</th><th class="n">دائن</th><th class="n">رصيد آخر المدة</th>${D ? '<th class="n a">منها مسودات</th>' : ""}</tr></thead><tbody>
          ${rows.length ? rows.map((x) => `<tr class="lk" data-party="${esc(x.p)}" data-s="${esc((x.p + " " + x.label).toLowerCase())}">
            <td class="nm">${esc(x.label)}${x.label !== x.p ? `<span class="sub">${esc(x.p)}</span>` : ""}${Math.abs(x.dn) > 0.005 ? '<span class="tag">مسودات</span>' : ""}</td>
            ${balTd(x.o)}${td(x.dr)}${td(x.cr)}${balTd(x.c, "s")}${D ? balTd(x.dn, "a") : ""}</tr>`).join("")
          : `<tr><td colspan="6" class="fv-empty">لا توجد أرصدة</td></tr>`}
          <tr class="grand"><td>الإجمالي</td>${balTd(T.o)}${td(T.dr)}${td(T.cr)}${balTd(T.c)}${D ? balTd(T.dn) : ""}</tr>
        </tbody></table></div>
        <div class="fv-note">اضغط على أي ${PARTY_ONE[pt]} لفتح كشف حسابه بالمسودات.</div>`;
    },
  };

  // ---------- النقدية والبنوك
  VIEWS.cash = {
    label: "النقدية والبنوك", k: "قائمة", t: "حركة النقدية والبنوك", search: true,
    run(model) {
