        const o = b.po + b.dop, i = b.pdr + b.ddr, out = b.pcr + b.dcr;
        return { n: nn, o, i, out, c: o + i - out, d: CL(b, "d") };
      }).filter((x) => [x.o, x.i, x.out].some((v) => Math.abs(v) > 0.005));
      const T = rows.reduce((t, x) => ({ o: t.o + x.o, i: t.i + x.i, out: t.out + x.out, c: t.c + x.c, d: t.d + x.d }), { o: 0, i: 0, out: 0, c: 0, d: 0 });
      return `<div class="fv-sum">
