          <div class="fv-c"><span>إجمالي المقبوضات</span><b>${fmt(T.i)}</b></div>
          <div class="fv-c"><span>إجمالي المدفوعات</span><b>${fmt(T.out)}</b></div>
          <div class="fv-c a"><span>رصيد آخر المدة</span><b>${fmt(T.c)}</b>${D ? `<small>منها مسودات ${fmt(T.d)}</small>` : ""}</div>
        </div>
        <div class="fv-tw"><table class="fv-t"><thead><tr><th>الحساب</th><th class="n">أول المدة</th><th class="n">مقبوضات</th><th class="n">مدفوعات</th><th class="n">آخر المدة</th>${D ? '<th class="n a">منها مسودات</th>' : ""}</tr></thead><tbody>
          ${rows.length ? rows.map((x) => `<tr class="lk" data-acc="${esc(x.n)}" data-s="${esc(accLabel(model.meta[x.n]).toLowerCase())}"><td class="nm">${esc(accLabel(model.meta[x.n]))}<span class="sub">${model.meta[x.n].account_type === "Bank" ? "بنك" : "نقدية"}</span></td>
            ${td(x.o)}${td(x.i)}${td(x.out)}${td(x.c, "s")}${D ? td(x.d, "a") : ""}</tr>`).join("") : `<tr><td colspan="6" class="fv-empty">مفيش حسابات نوعها Cash أو Bank</td></tr>`}
          <tr class="grand"><td>الإجمالي</td>${td(T.o)}${td(T.i)}${td(T.out)}${td(T.c)}${D ? td(T.d) : ""}</tr>
