  // ---------- المسودات
  VIEWS.drafts = {
    label: "المسودات", k: "مراجعة", t: "المستندات المسودة وأثرها المحاسبي", search: true,
    run(model) {
      if (!model.ctx.drafts) return `<div class="fv-err">شغّل «شامل المسودات» عشان تشوف المستندات المسودة.</div>`;
      const ds = model.drafts.slice().sort((a, b) => (a.date < b.date ? 1 : -1));
      const byDt = DRAFT_DOCTYPES.map((d) => ({ ...d, list: ds.filter((x) => x.dt === d.dt) }));
      const failed = ds.filter((d) => d.failed).length;
      return `<div class="fv-sum">
          ${byDt.map((d) => `<div class="fv-c"><span>${d.label}</span><b>${d.list.length}</b><small>${n2(d.list.reduce((s, x) => s + x.gl.reduce((t, g) => t + g.debit, 0), 0))}</small></div>`).join("")}
          <div class="fv-c a"><span>إجمالي المسودات</span><b>${ds.length}</b><small>${failed ? `${failed} تعذّر تحليلها` : "كلها اتحسبت ✓"}</small></div>
        </div>
        <div class="fv-tw"><table class="fv-t"><thead><tr><th>المستند</th><th>التاريخ</th><th>البيان / الطرف</th><th>الحسابات المتأثرة</th><th class="n">قيمة القيد</th></tr></thead><tbody>
          ${ds.length ? ds.map((d) => {
            const v = d.gl.reduce((t, g) => t + g.debit, 0);
            const accs = d.gl.slice(0, 4).map((g) => `${esc(accLabel(model.meta[g.account]) || g.account)} <small class="sub" style="display:inline">${g.debit ? "م " + n2(g.debit) : "د " + n2(g.credit)}</small>`).join("<br>");
            return `<tr class="lk" data-doc="${esc(d.dt)}|${esc(d.name)}" data-s="${esc((d.name + " " + d.title + " " + d.label).toLowerCase())}">
              <td class="nm">${esc(d.name)}<span class="sub">${esc(d.label)}</span></td>
              <td>${udate(d.date)}${d.inPeriod ? "" : '<span class="tag g">قبل الفترة</span>'}</td>
              <td>${esc(String(d.title || "").slice(0, 60))}</td>
              <td>${d.failed ? '<span class="tag g">تعذّر حساب القيد</span>' : accs + (d.gl.length > 4 ? `<br><small class="sub">+${d.gl.length - 4} سطور</small>` : "")}</td>
              ${td(v, "s")}</tr>`;
          }).join("") : `<tr><td colspan="5" class="fv-empty">مفيش مستندات مسودة حتى ${udate(model.ctx.to)}</td></tr>`}
        </tbody></table></div>
        <div class="fv-note">اضغط على أي مستند لفتحه في تاب جديد. قيود المسودات محسوبة بنفس منطق تقرير «${esc(CUSTOM_GL)}».</div>`;
