  // ---------- كشوف الحسابات
  VIEWS.st = {
    label: "كشوف الحسابات", k: "كشوف", t: "كشوف الحسابات", nomodel: true,
    async run(_m, V, body) {
      const p = V.preset;
      const toolbar = `<div class="chips no-print"><button data-pick="account">+ اختيار حسابات</button><button data-pick="party">+ اختيار عملاء / موردين</button></div>`;
      if (!p || !p.items || !p.items.length) {
        return `${toolbar}<div class="fv-empty">اختار حساب أو أكتر (أو أطراف) وهيطلعلك كشف مستقل لكل واحد — تقدر تطبعهم كلهم PDF أو Excel مرة واحدة.<br>أو اضغط على أي حساب / طرف في القوائم التانية.</div>`;
      }
      body.innerHTML = `${toolbar}<div class="fv-load"><div class="fv-pb"><i data-pbar></i></div><span data-plabel>جاري تجهيز الكشوف</span></div>`;
      const html = await buildStatements(p, V.ctx, (pct, label) => {
