  function parseLedger(res) {
    const rows = (res && res.result) || [];
    let opening = 0;
    const lines = [];
    rows.forEach((r) => {
      if (!r || Array.isArray(r)) return;
      if (isSummaryRow(r)) {
        const a = String(r.account || "").toLowerCase();
        if (/closing|ختام|إقفال|اقفال|total|إجمالي|اجمالي|مجموع/.test(a)) return;
        if (/opening|افتتاح/.test(a)) opening += flt(r.debit) - flt(r.credit);
        return;
      }
      if (!r.voucher_no && !r.posting_date) return;
      lines.push(r);
    });
    let bal = opening, dr = 0, cr = 0, drafts = 0;
    lines.forEach((r) => {
      dr += flt(r.debit); cr += flt(r.credit); bal += flt(r.debit) - flt(r.credit);
      r._bal = bal; r._draft = isDraftRow(r); if (r._draft) drafts++;
    });
    return { opening, lines, dr, cr, closing: bal, drafts };
  }

  async function buildStatements(p, ctx, progress) {
    const isParty = p.kind === "party";
    const out = [];
    for (let i = 0; i < p.items.length; i++) {
      progress(Math.round((100 * i) / p.items.length), `${i + 1} / ${p.items.length} · ${p.items[i]}`);
      const filters = {
        ...(ctx.extra || {}),
        company: ctx.company, from_date: ctx.from, to_date: ctx.to,
        ...draftFlags(!!ctx.drafts),
        ...(isParty ? { party_type: p.party_type, party: [p.items[i]] } : { account: [p.items[i]] }),
      };
      try { out.push({ name: p.items[i], ...parseLedger(await runReport(ctx.report || CUSTOM_GL, filters)) }); }
      catch (e) { out.push({ name: p.items[i], error: true, opening: 0, lines: [], dr: 0, cr: 0, closing: 0, drafts: 0 }); }
    }
    const period = `من ${udate(ctx.from)} إلى ${udate(ctx.to)}`;
    const kicker = isParty ? `كشف حساب ${PARTY_ONE[p.party_type] || ""}` : "كشف حساب";
    const tot = out.reduce((a, s) => ({ dr: a.dr + s.dr, cr: a.cr + s.cr, dc: a.dc + s.drafts }), { dr: 0, cr: 0, dc: 0 });
    const bt = (v) => (flt(v, 2) ? `${n2(Math.abs(v))} <small>${v > 0 ? "مدين" : "دائن"}</small>` : "0.00");
    let html = out.length > 1 ? `<div class="st-index no-print">${out.map((s, i) => `<a data-jump="st-${i}">${esc(s.name)}</a>`).join("")}</div>` : "";
    html += `<div class="fv-sum"><div class="fv-c"><span>عدد الكشوف</span><b>${out.length}</b></div>
      <div class="fv-c"><span>إجمالي المدين</span><b>${n2(tot.dr)}</b></div><div class="fv-c"><span>إجمالي الدائن</span><b>${n2(tot.cr)}</b></div>
      <div class="fv-c a"><span>سطور مسودة</span><b>${tot.dc}</b></div></div>`;
    out.forEach((s, i) => {
      html += `<section class="st" id="st-${i}"><div class="st-head">
          <div><div class="fv-k">${esc(kicker)}</div><h3>${esc(s.name)}</h3><div class="fv-meta">${esc(period)} · ${esc(ctx.company)}</div></div>
          <div class="st-chips"><div class="st-chip"><span>رصيد أول المدة</span><b>${bt(s.opening)}</b></div><div class="st-chip"><span>مدين</span><b>${n2(s.dr)}</b></div>
          <div class="st-chip"><span>دائن</span><b>${n2(s.cr)}</b></div><div class="st-chip a"><span>رصيد آخر المدة</span><b>${bt(s.closing)}</b></div></div></div>`;
      if (s.error) { html += `<div class="fv-empty">حصل خطأ أثناء تشغيل التقرير لهذا البند.</div></section>`; return; }
      html += `<table class="fv-t"><thead><tr><th>التاريخ</th><th>نوع المستند</th><th>رقم المستند</th><th>${isParty ? "الحساب" : "الطرف / المقابل"}</th><th>البيان</th><th class="n">مدين</th><th class="n">دائن</th><th class="n">الرصيد</th></tr></thead><tbody>
        <tr class="tot"><td colspan="5">رصيد أول المدة</td><td></td><td></td>${balTd(s.opening)}</tr>
        ${s.lines.length ? "" : '<tr><td colspan="8" class="fv-empty">لا توجد حركة خلال الفترة</td></tr>'}
        ${s.lines.map((r) => {
          const other = isParty ? r.account : r.party || r.against || r.against_account || "";
          return `<tr class="${r._draft ? "dr" : ""}"><td>${udate(r.posting_date)}</td><td>${esc(__(r.voucher_type || ""))}</td>
            <td>${esc(r.voucher_no)}${r._draft ? '<span class="tag">مسودة</span>' : ""}</td><td>${esc(String(other).slice(0, 60))}</td>
            <td>${esc(String(r.remarks || r.user_remark || "").slice(0, 120))}</td>${td(r.debit)}${td(r.credit)}${balTd(r._bal)}</tr>`;
        }).join("")}
        <tr class="grand"><td colspan="5">الإجمالي / رصيد آخر المدة</td>${td(s.dr)}${td(s.cr)}${balTd(s.closing)}</tr></tbody></table></section>`;
    });
    return html;
  }

  function pickDialog(kind, ctx, onDone, presetType) {
    const isParty = kind === "party";
    const d = new frappe.ui.Dialog({
      title: isParty ? "اختيار الأطراف" : "اختيار الحسابات",
      fields: [
        ...(isParty ? [{ fieldname: "party_type", label: "نوع الطرف", fieldtype: "Select", options: PARTY_TYPES.join("\n"), default: presetType || "Customer", reqd: 1, onchange: () => d.set_value("items", []) }] : []),
        {
          fieldname: "items", label: isParty ? "الأطراف" : "الحسابات", fieldtype: "MultiSelectList", reqd: 1,
          get_data: (txt) => (isParty ? frappe.db.get_link_options(d.get_value("party_type") || "Customer", txt) : frappe.db.get_link_options("Account", txt, { company: ctx.company, is_group: 0 })),
        },
      ],
      primary_action_label: "إنشاء الكشوف",
      primary_action: (v) => {
        if (!v.items || !v.items.length) return frappe.msgprint("اختار بند واحد على الأقل");
