  // ============================================================ تحويل العرض الحالي لـ Excel
  function cellText(c) {
    const k = c.cloneNode(true);
    k.querySelectorAll(".cr").forEach((e) => e.remove());
    k.querySelectorAll(".tag").forEach((e) => (e.textContent = ` [${e.textContent}]`));
    k.querySelectorAll(".sub").forEach((e) => (e.textContent = ` — ${e.textContent}`));
    k.querySelectorAll("br").forEach((e) => e.replaceWith(" | "));
    return k.textContent.replace(/\s+/g, " ").trim();
  }
  function tableToRows(body, title, meta) {
    const rows = [[{ v: title, s: 7 }], [{ v: meta, s: 8 }], []];
    body.querySelectorAll(".st-head h3, table.fv-t").forEach((el) => {
      if (el.tagName === "H3") { rows.push([{ v: el.textContent.trim(), s: 7 }]); return; }
      el.querySelectorAll("tr").forEach((tr) => {
        if (tr.classList.contains("hid")) return;
        const isHead = !!tr.closest("thead"), sec = tr.classList.contains("sec"), grand = tr.classList.contains("grand"),
          tot = tr.classList.contains("tot"), grp = tr.classList.contains("g"), dr = tr.classList.contains("dr");
        const depth = +(tr.dataset.d || 0);
        const r = [];
        Array.from(tr.children).forEach((c, ci) => {
          const num = c.dataset.v != null;
          let s;
          if (isHead || tot) s = num ? 10 : 4;
          else if (sec || grand) s = num ? 6 : 5;
          else if (grp) s = num ? 3 : 2;
          else if (num && (c.classList.contains("a") || dr)) s = 9;
          else s = num ? 1 : 0;
          const text = ci === 0 && depth ? "    ".repeat(depth) + cellText(c) : cellText(c);
          r.push(num ? { v: flt(c.dataset.v, 2), n: true, s } : { v: text, s });
          const span = +(c.getAttribute("colspan") || 1);
          for (let k = 1; k < span; k++) r.push({ v: "", s });
        });
        rows.push(r);
      });
      rows.push([]);
    });
    return rows;
  }

  // ============================================================ العارض (Tabs + أدوات)
  const TAB_ORDER = ["overview", "bs", "pl", "tb", "party", "cash", "drafts", "st"];

  function createViewer(host, ctx, opts) {
    opts = opts || {};
    const V = { ctx, tab: opts.tab || "overview", level: "3", q: "", party: opts.party || "Customer", preset: opts.preset || null, token: 0 };
    host.innerHTML = `<div class="fv">
      <nav class="fv-tabs">${TAB_ORDER.map((t) => `<button data-tab="${t}">${VIEWS[t].label}</button>`).join("")}</nav>
      <div class="fv-bar"><div><div class="fv-k" data-k></div><h3 data-h></h3><div class="fv-meta" data-m></div></div>
        <div class="fv-tools">
          <input data-q placeholder="بحث…" />
          <select data-level><option value="1">المستوى 1</option><option value="2">المستوى 2</option><option value="3">المستوى 3</option><option value="4">المستوى 4</option><option value="">كل المستويات</option></select>
          <button class="fv-btn" data-xls>تصدير Excel</button><button class="fv-btn p" data-print>طباعة / PDF</button>
        </div></div>
      <div data-body></div></div>`;
    const q = (s) => host.querySelector(s);
    const body = q("[data-body]");
    q("[data-level]").value = V.level;

    function applyRows() {
      let hideBelow = Infinity;
      body.querySelectorAll("tr[data-d]").forEach((r) => {
        const d = +r.dataset.d;
        if (d <= hideBelow) hideBelow = Infinity;
        const hc = d > hideBelow;
        r.classList.toggle("hc", hc);
        if (!hc && r.classList.contains("col")) hideBelow = d;
      });
      const term = V.q.trim().toLowerCase();
      body.querySelectorAll("tbody tr[data-s]").forEach((r) => r.classList.toggle("hid", term ? !r.dataset.s.includes(term) : r.classList.contains("hc")));
    }
    function applyLevel() {
      const lv = V.level ? +V.level : 0;
      body.querySelectorAll("tr[data-g]").forEach((r) => r.classList.toggle("col", !!lv && +r.dataset.d === lv - 1));
      applyRows();
    }

    async function render() {
      const token = ++V.token;
      const view = VIEWS[V.tab];
      host.querySelectorAll("[data-tab]").forEach((b) => b.classList.toggle("on", b.dataset.tab === V.tab));
      q("[data-k]").textContent = view.k;
      q("[data-h]").textContent = V.tab === "party" ? `ميزان ${PARTY_AR[V.party]}` : view.t;
      q("[data-m]").textContent = `${V.ctx.company} · من ${udate(V.ctx.from)} إلى ${udate(V.ctx.to)} · ${V.ctx.drafts ? "شامل القيود المسودة" : "القيود المرحّلة فقط"}`;
      q("[data-level]").classList.toggle("fv-hide", !view.tree);
      q("[data-q]").classList.toggle("fv-hide", !(view.tree || view.search));
      if (!V.ctx.company || !V.ctx.from || !V.ctx.to) { body.innerHTML = `<div class="fv-err">اختار الشركة والفترة.</div>`; return; }
      body.innerHTML = `<div class="fv-load"><div class="fv-pb"><i data-pbar></i></div><span data-plabel>جاري الحساب…</span></div>`;
      const progress = (pct, label) => {
        if (token !== V.token) return;
        const i = body.querySelector("[data-pbar]"), l = body.querySelector("[data-plabel]");
        if (i) i.style.width = pct + "%";
        if (l) l.textContent = label;
      };
      try {
        const model = view.nomodel ? null : await getModel(V.ctx, progress);
        if (token !== V.token) return;
        const html = await view.run(model, V, body);
        if (token !== V.token) return;
        body.innerHTML = html;
        if (view.tree) applyLevel(); else applyRows();
      } catch (e) {
        if (token !== V.token) return;
        console.error(e);
        body.innerHTML = `<div class="fv-err">${esc(e.message || e)}<br><button class="fv-btn" data-retry>إعادة المحاولة</button></div>`;
      }
    }

    host.addEventListener("click", (e) => {
      const t = e.target.closest("[data-tab],[data-goto],[data-retry],[data-pt],[data-pick],[data-jump],[data-print],[data-xls],tr[data-g],tr[data-acc],tr[data-party],tr[data-doc]");
      if (!t || !host.contains(t)) return;
      if (t.dataset.tab || t.dataset.goto) { V.tab = t.dataset.tab || t.dataset.goto; V.q = ""; q("[data-q]").value = ""; return render(); }
      if (t.hasAttribute("data-retry")) { clearCache(); return render(); }
      if (t.dataset.pt) { V.party = t.dataset.pt; return render(); }
      if (t.dataset.pick) return pickDialog(t.dataset.pick, V.ctx, (p) => { V.preset = p; V.tab = "st"; render(); }, V.party);
      if (t.dataset.jump) { const s = body.querySelector("#" + t.dataset.jump); return s && s.scrollIntoView({ behavior: "smooth", block: "start" }); }
      if (t.hasAttribute("data-print")) return printView();
      if (t.hasAttribute("data-xls")) return exportXlsx();
      if (t.matches("tr[data-g]")) { if (!e.target.closest("td.nm")) return; t.classList.toggle("col"); return applyRows(); }
      if (t.matches("tr[data-acc]")) { V.preset = { kind: "account", items: [t.dataset.acc] }; V.tab = "st"; return render(); }
      if (t.matches("tr[data-party]")) { V.preset = { kind: "party", party_type: V.party, items: [t.dataset.party] }; V.tab = "st"; return render(); }
      if (t.matches("tr[data-doc]")) { const [dt, name] = t.dataset.doc.split("|"); return window.open(`/app/${frappe.router.slug(dt)}/${encodeURIComponent(name)}`, "_blank"); }
    });
    q("[data-level]").addEventListener("change", (e) => { V.level = e.target.value; applyLevel(); });
    q("[data-q]").addEventListener("input", (e) => { V.q = e.target.value; applyRows(); });

    function printView() {
      const w = window.open("", "_blank");
      if (!w) return frappe.msgprint("المتصفح منع نافذة الطباعة — اسمح بالـ Pop-ups للموقع.");
      const wide = V.tab === "tb" || (V.ctx.drafts && ["bs", "pl"].includes(V.tab));
      w.document.write(`<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>${esc(q("[data-h]").textContent)}</title>
        <style>${VIEW_CSS}${PRINT_CSS}${wide ? "@page{size:A4 landscape}" : ""}</style></head><body><div class="fv">
        <div class="ph"><div><div class="k">${esc(q("[data-k]").textContent)}</div><h1>${esc(q("[data-h]").textContent)}</h1></div>
        <div>${esc(q("[data-m]").textContent)}<br>طُبع في ${esc(frappe.datetime.now_datetime())} · ${esc(frappe.session.user_fullname || frappe.session.user)}</div></div>
        ${body.innerHTML}</div><script>window.onload=function(){setTimeout(function(){window.print()},350)}<\/script></body></html>`);
      w.document.close();
    }
    function exportXlsx() {
      if (!body.querySelector("table")) return frappe.msgprint("مفيش جدول للتصدير في الشاشة دي.");
      const title = q("[data-h]").textContent;
      XLSX.download(`${title} ${V.ctx.from} - ${V.ctx.to}.xlsx`, VIEWS[V.tab].label, tableToRows(body, title, q("[data-m]").textContent));
    }

    V.setCtx = (c) => { V.ctx = c; render(); };
    V.refresh = () => { clearCache(); render(); };
    render();
    return V;
  }

  function openViewerDialog(ctx, opts) {
    const d = new frappe.ui.Dialog({ title: "مركز القوائم المالية الشاملة", size: "extra-large", fields: [{ fieldtype: "HTML", fieldname: "v" }] });
    d.show();
    createViewer(d.fields_dict.v.$wrapper[0], ctx, opts);
  }

  // ============================================================ زرار "مركز القوائم" جوه تقارير الأستاذ
  const LEDGER_REPORTS = [CUSTOM_GL, "General Ledger"];
  const BTN_GROUP = "مركز القوائم";
  const SKIP_KEYS = ["company", "from_date", "to_date", "account", "party", "party_type", "group_by", ...DRAFT_KEYS];

  function ctxFromReport(qr) {
    const f = (qr.get_filter_values && qr.get_filter_values(false)) || {};
    const dk = DRAFT_KEYS.find((k) => k in f);
    const extra = {};
    Object.keys(f).forEach((k) => { if (!SKIP_KEYS.includes(k) && f[k] !== "" && f[k] != null) extra[k] = f[k]; });
    const list = (v) => (Array.isArray(v) ? v : v ? [v] : []);
    return {
      ctx: { company: f.company, from: f.from_date, to: f.to_date, drafts: dk ? !!cint(f[dk]) : true, report: qr.report_name, extra },
      accounts: list(f.account), parties: list(f.party), party_type: f.party_type,
    };
  }

  function addLedgerButtons(qr) {
    const go = (tab, withPreset) => () => {
      const c = ctxFromReport(frappe.query_report);
      if (!c.ctx.company || !c.ctx.from || !c.ctx.to) return frappe.msgprint("حدد الشركة والفترة في فلاتر التقرير الأول");
      let preset = null;
      if (withPreset === "account" && c.accounts.length) preset = { kind: "account", items: c.accounts };
      if (withPreset === "party" && c.parties.length && c.party_type) preset = { kind: "party", party_type: c.party_type, items: c.parties };
      openViewerDialog(c.ctx, { tab, preset, party: PARTY_TYPES.includes(c.party_type) ? c.party_type : "Customer" });
    };
    [
      ["كشف مستقل لكل حساب مختار", go("st", "account")],
      ["كشف مستقل لكل طرف مختار", go("st", "party")],
      ["نظرة عامة", go("overview")],
      ["قائمة المركز المالي", go("bs")],
      ["قائمة الدخل", go("pl")],
      ["ميزان المراجعة الشامل", go("tb")],
      ["موازين الأطراف", go("party")],
      ["النقدية والبنوك", go("cash")],
      ["المستندات المسودة", go("drafts")],
    ].forEach(([l, fn]) => qr.page.add_inner_button(l, fn, BTN_GROUP));
    const $g = qr.page.get_inner_group_button ? qr.page.get_inner_group_button(BTN_GROUP) : null;
    if ($g && $g.length) { $g.addClass("fh-ledger-group"); $g.find("> button").css({ background: ACCENT, color: "#fff", borderColor: ACCENT }); }
  }

  function syncLedgerButtons() {
    const route = frappe.get_route();
    const qr = frappe.query_report;
    jQuery(".fh-ledger-group").each(function () {
      const mine = qr && qr.page && jQuery(this).closest(qr.page.wrapper).length && LEDGER_REPORTS.includes(qr.report_name) && route[1] === qr.report_name;
      if (!mine) jQuery(this).remove();
    });
    if (route[0] !== "query-report" || !LEDGER_REPORTS.includes(route[1])) return;
    let tries = 0;
    const wait = setInterval(() => {
      const qq = frappe.query_report;
      if (++tries > 40) return clearInterval(wait);
      if (!qq || !qq.page || qq.report_name !== route[1] || !qq.filters || !qq.filters.length) return;
      clearInterval(wait);
      if (!jQuery(qq.page.wrapper).find(".fh-ledger-group").length) addLedgerButtons(qq);
    }, 250);
  }
  window.FinanceHub = { syncLedgerButtons, openViewerDialog };
  if (!window.__fhLedgerHook && frappe.router && frappe.router.on) {
    window.__fhLedgerHook = true;
    frappe.router.on("change", () => window.FinanceHub && window.FinanceHub.syncLedgerButtons());
  }
  setTimeout(syncLedgerButtons, 0);

  // ============================================================ الداشبورد (البلوك)
  const ROOT = typeof root_element !== "undefined" ? root_element : null;
  if (!ROOT || !ROOT.querySelector("[data-viewer]")) return;
  injectCss(ROOT, "fh-view-css-v2");
  const $1 = (s) => ROOT.querySelector(s);
  const $all = (s) => Array.from(ROOT.querySelectorAll(s));
  const state = { company: null, from: null, to: null, drafts: true };
  let viewer = null;

  function setPreset(p) {
    const t = frappe.datetime.str_to_obj(frappe.datetime.get_today());
    const ymd = (d) => frappe.datetime.obj_to_str(d);
    let from, to;
    if (p === "month") { from = new Date(t.getFullYear(), t.getMonth(), 1); to = new Date(t.getFullYear(), t.getMonth() + 1, 0); }
    else if (p === "prev_month") { from = new Date(t.getFullYear(), t.getMonth() - 1, 1); to = new Date(t.getFullYear(), t.getMonth(), 0); }
    else if (p === "quarter") { const qq = Math.floor(t.getMonth() / 3) * 3; from = new Date(t.getFullYear(), qq, 1); to = new Date(t.getFullYear(), qq + 3, 0); }
    else {
      const fy = fiscalYear(frappe.datetime.get_today());
      from = frappe.datetime.str_to_obj(fy.start || `${t.getFullYear()}-01-01`);
      to = p === "ytd" ? t : frappe.datetime.str_to_obj(fy.end || `${t.getFullYear()}-12-31`);
    }
    $1("[data-from]").value = ymd(from);
    $1("[data-to]").value = ymd(to);
    $all("[data-preset]").forEach((b) => b.classList.toggle("active", b.dataset.preset === p));
    onChange();
  }

  let deb;
  function onChange() {
    state.company = $1("[data-company]").value;
    state.from = $1("[data-from]").value;
    state.to = $1("[data-to]").value;
    state.drafts = $1("[data-drafts]").checked;
    if (state.from && state.to && state.from > state.to) return frappe.show_alert({ message: "تاريخ البداية بعد تاريخ النهاية", indicator: "orange" });
    clearTimeout(deb);
    deb = setTimeout(() => {
      const ctx = { ...state };
      if (!viewer) viewer = createViewer($1("[data-viewer]"), ctx);
      else viewer.setCtx(ctx);
    }, 300);
  }

  (async function init() {
    const companies = await frappe.db.get_list("Company", { fields: ["name"], limit: 100 });
    const def = frappe.defaults.get_user_default("Company") || (companies[0] && companies[0].name);
    $1("[data-company]").innerHTML = companies.map((c) => `<option value="${esc(c.name)}" ${c.name === def ? "selected" : ""}>${esc(c.name)}</option>`).join("");
    $1("[data-company]").addEventListener("change", onChange);
    ["[data-from]", "[data-to]"].forEach((s) => $1(s).addEventListener("change", () => { $all("[data-preset]").forEach((b) => b.classList.remove("active")); onChange(); }));
    $1("[data-drafts]").addEventListener("change", onChange);
    $1("[data-refresh]").addEventListener("click", () => viewer && viewer.refresh());
    $all("[data-preset]").forEach((b) => b.addEventListener("click", () => setPreset(b.dataset.preset)));
    setPreset("ytd");
  })().catch((e) => console.error("Finance Hub:", e));
})();

style:
/* ====== اللون الثاني (التمييز) — غيّره من هنا بس ====== */
:host { --fh-accent: #0E5E6F; }

.fh {
  --acc: var(--fh-accent, #0E5E6F);
  --g50:  var(--gray-50,  #F8F8F8);
  --g100: var(--gray-100, #F3F3F3);
  --g200: var(--gray-200, #EDEDED);
  --g300: var(--gray-300, #E2E2E2);
  --g500: var(--gray-500, #999999);
  --g600: var(--gray-600, #7C7C7C);
  --g700: var(--gray-700, #525252);
  --g900: var(--gray-900, #171717);
  --card: var(--card-bg, #FFFFFF);
  direction: rtl;
  color: var(--text-color, #171717);
  font-family: inherit;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding-bottom: 8px;
}
.fh * { box-sizing: border-box; }

/* ---------- Hero / filters ---------- */
.fh-hero {
  background: var(--g100);
  border-radius: 14px;
  padding: 20px 22px 16px;
  display: flex; flex-direction: column; gap: 16px;
}
.fh-hero-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; }
.fh-kicker { font-size: 11px; font-weight: 600; color: var(--acc); letter-spacing: .4px; }
.fh-title  { margin: 2px 0 4px; font-size: 22px; font-weight: 700; color: var(--g900); }
.fh-sub    { font-size: 13px; color: var(--g600); }

.fh-filters { display: grid; grid-template-columns: 2fr 1fr 1fr auto; gap: 12px; align-items: end; }
.fh-field { display: flex; flex-direction: column; gap: 5px; font-size: 12px; color: var(--g700); }
.fh-field select, .fh-field input {
  height: 36px; border: 1px solid var(--g300); border-radius: 8px;
  background: var(--card); color: var(--g900); padding: 0 10px; font: inherit; font-size: 13px;
}
.fh-field select:focus, .fh-field input:focus { outline: none; border-color: var(--acc); box-shadow: 0 0 0 3px color-mix(in srgb, var(--acc) 15%, transparent); }

.fh-switch { display: inline-flex; align-items: center; gap: 8px; height: 36px; cursor: pointer; font-size: 13px; color: var(--g900); user-select: none; }
.fh-switch input { display: none; }
.fh-switch i { width: 36px; height: 20px; border-radius: 20px; background: var(--g300); position: relative; transition: .2s; }
.fh-switch i::after { content: ""; position: absolute; top: 2px; right: 2px; width: 16px; height: 16px; border-radius: 50%; background: #fff; transition: .2s; }
.fh-switch input:checked + i { background: var(--acc); }
.fh-switch input:checked + i::after { right: 18px; }

.fh-presets { display: flex; flex-wrap: wrap; gap: 6px; }
.fh-presets button {
  border: 1px solid var(--g300); background: var(--card); color: var(--g700);
  font: inherit; font-size: 12px; padding: 5px 12px; border-radius: 20px; cursor: pointer; transition: .15s;
}
.fh-presets button:hover  { border-color: var(--acc); color: var(--acc); }
.fh-presets button.active { background: var(--acc); border-color: var(--acc); color: #fff; }

.fh-btn { font: inherit; font-size: 13px; border-radius: 8px; padding: 7px 14px; cursor: pointer; border: 1px solid var(--g300); background: var(--card); color: var(--g900); }
.fh-btn:hover { border-color: var(--acc); color: var(--acc); }

@media (max-width: 760px) {
  .fh-filters { grid-template-columns: 1fr 1fr; }
  .fh-field-wide { grid-column: 1 / -1; }
}

script:
// Fixed Assets 360 — Custom HTML Block script (root_element = shadow root)
(function () {
	const R = root_element;
	const REPORT = "Asset Register 360";
	const STATUSES = ["Draft", "Submitted", "Partially Depreciated", "Fully Depreciated", "Sold", "Scrapped",
		"In Maintenance", "Out of Order", "Issue", "Receipt", "Capitalized", "Decapitalized", "Work In Progress", "Cancelled"];
	const STATUS_COLORS = {
		"Draft": "#f5a524", "Submitted": "#4f6bed", "Partially Depreciated": "#3b82f6", "Fully Depreciated": "#22a06b",
		"Sold": "#e5484d", "Scrapped": "#b42318", "In Maintenance": "#eab308", "Out of Order": "#f97316",
		"Capitalized": "#8e4ec6", "Decapitalized": "#a78bfa", "Cancelled": "#9ca3af", "Work In Progress": "#06b6d4",
		"Issue": "#14b8a6", "Receipt": "#64748b",
	};
	const PALETTE = ["#4f6bed", "#22a06b", "#f5a524", "#e5484d", "#8e4ec6", "#06b6d4", "#f97316", "#64748b", "#db2777", "#84cc16"];
	const COLS = [
		["asset", "Asset"], ["asset_name", "Asset Name"], ["asset_category", "Category"], ["status", "Status"],
		["location", "Location"], ["cost_center", "Cost Center"], ["source_doc", "Source Doc"],
		["purchase_date", "Purchase Date"], ["closing_cost", "Cost", 1], ["closing_acc_dep", "Acc. Dep.", 1],
		["closing_nbv", "NBV", 1], ["dep_period", "Dep. (Period)", 1], ["gain_loss", "Gain/(Loss)", 1], ["variance", "Variance", 1],
	];
	const NUMS = ["opening_cost", "additions", "cap_repairs", "disposal_cost", "closing_cost", "opening_acc_dep",
		"acc_dep_brought_in", "dep_period", "value_adj_period", "acc_dep_eliminated", "closing_acc_dep", "opening_nbv",
		"closing_nbv", "sale_amount", "gain_loss", "variance"];

	const q = (s) => R.querySelector(s);
	const qa = (s) => Array.from(R.querySelectorAll(s));
	const ref = (n) => q(`[data-ref="${n}"]`);
	const esc = (v) => frappe.utils.escape_html(v == null ? "" : String(v));
	const st = { raw: [], rows: [], drill: {}, search: "", sort: { f: "closing_cost", d: -1 }, limit: 150, currency: null, rawLen: 0 };
	const ms = {};

	// ---------- formatting ----------
	const money = (v) => format_currency(v || 0, st.currency, 2);
	const compact = (v) => {
		v = v || 0; const a = Math.abs(v);
		const s = a >= 1e9 ? (v / 1e9).toFixed(2) + "B" : a >= 1e6 ? (v / 1e6).toFixed(2) + "M" : a >= 1e3 ? (v / 1e3).toFixed(1) + "K" : v.toFixed(0);
		return s;
	};
	const dt = (v) => (v ? frappe.datetime.str_to_user(String(v).substring(0, 10)) : "");

	// ---------- multiselect ----------
	function makeMS(el, loader) {
		const o = { el, values: [], options: null, loader };
		el.innerHTML = `<button class="a3-ms-btn" type="button">All</button>
			<div class="a3-ms-pop"><input type="text" placeholder="Search…"><div class="a3-ms-list"></div>
			<div class="a3-ms-foot"><a data-x="all">Select all</a><a data-x="clear">Clear</a></div></div>`;
		const btn = el.querySelector(".a3-ms-btn"), list = el.querySelector(".a3-ms-list"), inp = el.querySelector("input");
		const paint = () => {
			const t = (inp.value || "").toLowerCase();
			list.innerHTML = (o.options || []).filter((x) => !t || x.toLowerCase().includes(t))
				.map((x) => `<label><input type="checkbox" value="${esc(x)}" ${o.values.includes(x) ? "checked" : ""}> ${esc(x)}</label>`).join("")
				|| `<div class="a3-empty" style="padding:10px">No options</div>`;
		};
		o.refresh = () => {
			btn.textContent = !o.values.length ? "All" : o.values.length === 1 ? o.values[0] : o.values.length + " selected";
			btn.classList.toggle("on", !!o.values.length);
		};
		o.set = (vals) => { o.values = vals || []; o.refresh(); if (o.options) paint(); };
		btn.addEventListener("click", async (e) => {
			e.stopPropagation();
			qa(".a3-ms.open").forEach((x) => x !== el && x.classList.remove("open"));
			el.classList.toggle("open");
			if (!o.options) { list.innerHTML = `<div class="a3-empty" style="padding:10px">Loading…</div>`; o.options = await o.loader(); }
			paint(); inp.focus();
		});
		inp.addEventListener("input", paint);
		list.addEventListener("change", (e) => {
			const v = e.target.value;
			o.values = e.target.checked ? [...o.values, v] : o.values.filter((x) => x !== v);
			o.refresh();
		});
		el.querySelector(".a3-ms-foot").addEventListener("click", (e) => {
			const x = e.target.dataset.x; if (!x) return;
			o.values = x === "all" ? (o.options || []).slice() : []; o.refresh(); paint();
		});
		el.querySelector(".a3-ms-pop").addEventListener("click", (e) => e.stopPropagation());
		o.refresh();
		return o;
	}
	const linkLoader = (doctype, filters) => () =>
		frappe.db.get_list(doctype, { fields: ["name"], filters: filters ? filters() : {}, limit: 2000, order_by: "name asc" })
			.then((r) => r.map((x) => x.name));

	// stop typing inside the dashboard from reaching ERPNext global shortcuts / awesome bar
	["keydown", "keyup", "keypress"].forEach((ev) => R.addEventListener(ev, (e) => {
		const t = e.composedPath()[0];
		if (t && (t.tagName === "INPUT" || t.tagName === "SELECT" || t.tagName === "TEXTAREA")) {
			e.stopPropagation();
			if (ev === "keydown" && e.key === "Enter" && t.dataset.ref !== "search" && t.type !== "text") run();
		}
	}));

	R.addEventListener("click", () => qa(".a3-ms.open").forEach((x) => x.classList.remove("open")));
	document.addEventListener("click", (e) => { if (!e.composedPath().includes(R.host)) qa(".a3-ms.open").forEach((x) => x.classList.remove("open")); });

	ms.status = makeMS(q('[data-ms="status"]'), () => Promise.resolve(STATUSES.slice()));
	ms.asset_category = makeMS(q('[data-ms="asset_category"]'), linkLoader("Asset Category"));
	ms.location = makeMS(q('[data-ms="location"]'), linkLoader("Location"));
	ms.cost_center = makeMS(q('[data-ms="cost_center"]'), linkLoader("Cost Center", () => ({ company: fv("company"), is_group: 0 })));
	ms.department = makeMS(q('[data-ms="department"]'), linkLoader("Department"));

	// ---------- filters ----------
	const fe = (n) => q(`[data-f="${n}"]`);
	const fv = (n) => { const e = fe(n); return e.type === "checkbox" ? (e.checked ? 1 : 0) : e.value; };
	function getFilters() {
		const f = {
			company: fv("company"), from_date: fv("from_date"), to_date: fv("to_date"),
			source_type: fv("source_type"), finance_book: fv("finance_book"), include_default_book: 1,
			include_disposed_before: fv("include_disposed_before"), hide_zero_rows: fv("hide_zero_rows"),
		};
		Object.keys(ms).forEach((k) => { if (ms[k].values.length) f[k] = ms[k].values; });
		Object.keys(f).forEach((k) => { if (f[k] === "" || f[k] == null) delete f[k]; });
		return f;
	}
	function setDefaults() {
		const today = frappe.datetime.get_today();
		fe("to_date").value = today;
		fe("from_date").value = frappe.datetime.year_start ? frappe.datetime.year_start() : today.substring(0, 4) + "-01-01";
		fe("source_type").value = ""; fe("finance_book").value = "";
		fe("include_disposed_before").checked = false; fe("hide_zero_rows").checked = false;
		Object.values(ms).forEach((m) => m.set([]));
		st.drill = {}; st.search = ""; ref("search").value = "";
	}

	async function init() {
		const companies = await frappe.db.get_list("Company", { fields: ["name"], limit: 100 });
		const def = frappe.defaults.get_user_default("Company") || (companies[0] && companies[0].name);
		fe("company").innerHTML = companies.map((c) => `<option ${c.name === def ? "selected" : ""}>${esc(c.name)}</option>`).join("");
		const fbs = await frappe.db.get_list("Finance Book", { fields: ["name"], limit: 100 }).catch(() => []);
		fe("finance_book").innerHTML = `<option value="">Default</option>` + fbs.map((x) => `<option>${esc(x.name)}</option>`).join("");
		setDefaults();
		run();
	}

	// ---------- data ----------
	async function run() {
		const f = getFilters();
		if (!f.company) return;
		q(".a3").classList.add("busy");
		try {
			const r = await frappe.call({ method: "frappe.desk.query_report.run", args: { report_name: REPORT, filters: f, ignore_prepared_report: 1 } });
			const m = r.message || {};
			const result = m.result || [];
			st.rawLen = result.length;
			st.raw = [];
			result.forEach((x, i) => { if (x && x.asset && !x.is_group && !x.is_total) { x.ridx = i; st.raw.push(x); } });
			const cur = await frappe.db.get_value("Company", f.company, "default_currency");
			st.currency = (cur && cur.message && cur.message.default_currency) || frappe.boot.sysdefaults.currency;
			st.lastFilters = f;
			ref("subtitle").textContent = `${f.company} · ${dt(f.from_date)} → ${dt(f.to_date)} · updated ${frappe.datetime.now_time()}`;
			render();
		} catch (e) {
			console.error(e);
			ref("kpis").innerHTML = `<div class="a3-empty">Could not load the report "${REPORT}". Check it exists and server scripts are enabled.</div>`;
		} finally {
			q(".a3").classList.remove("busy");
		}
	}

	function applyLocal() {
		const s = st.search.toLowerCase();
		let rows = st.raw.filter((r) => {
			for (const k in st.drill) if (String(r[k] || "(Not Set)") !== st.drill[k]) return false;
			if (!s) return true;
			return ["asset", "asset_name", "asset_category", "location", "cost_center", "purchase_invoice", "purchase_receipt",
				"supplier", "source_doc", "status", "custodian", "department", "item_code"].some((k) => String(r[k] || "").toLowerCase().includes(s));
		});
		const { f, d } = st.sort;
		rows.sort((a, b) => {
			const x = a[f], y = b[f];
			if (typeof x === "number" || typeof y === "number") return ((x || 0) - (y || 0)) * d;
			return String(x || "").localeCompare(String(y || "")) * d;
		});
		st.rows = rows;
	}
	const sum = (rows, f) => rows.reduce((a, r) => a + (r[f] || 0), 0);

	// ---------- render ----------
	function render() {
		applyLocal();
		renderChips(); renderKPIs(); renderBars(); renderDonut(); renderRF(); renderYears(); renderTable();
	}

	function renderChips() {
		const labels = { asset_category: "Category", location: "Location", cost_center: "Cost Center", department: "Department",
			supplier: "Supplier", source_type: "Source", custodian: "Custodian", status: "Status", purchase_year: "Year" };
		ref("chips").innerHTML = Object.keys(st.drill).map((k) =>
			`<span class="a3-chip" data-k="${k}">${labels[k] || k}: ${esc(st.drill[k])}<b>×</b></span>`).join("") +
			(Object.keys(st.drill).length > 1 ? `<span class="a3-chip" data-k="*">Clear all<b>×</b></span>` : "");
	}

	function renderKPIs() {
		const r = st.rows;
		const drafts = r.filter((x) => x.status === "Draft");
		const disposed = r.filter((x) => x.disposal_cost);
		const varN = r.filter((x) => Math.abs(x.variance || 0) > 0.5).length;
		const gl = sum(r, "gain_loss");
		const cost = sum(r, "closing_cost"), nbv = sum(r, "closing_nbv");
		const k = [
			["Assets", r.length, `${drafts.length} draft · ${disposed.length} disposed`, "#4f6bed", 1],
			["Closing Cost", cost, `Opening ${compact(sum(r, "opening_cost"))}`, "#4f6bed"],
			["Accumulated Dep.", sum(r, "closing_acc_dep"), `${cost ? ((sum(r, "closing_acc_dep") / cost) * 100).toFixed(1) : 0}% of cost`, "#e5484d"],
			["Net Book Value", nbv, `${cost ? ((nbv / cost) * 100).toFixed(1) : 0}% remaining`, "#22a06b"],
			["Depreciation (Period)", sum(r, "dep_period"), `Value adj. ${compact(sum(r, "value_adj_period"))}`, "#f97316"],
			["Additions", sum(r, "additions") + sum(r, "cap_repairs"), `Repairs ${compact(sum(r, "cap_repairs"))}`, "#06b6d4"],
			["Disposals (Cost)", sum(r, "disposal_cost"), `Sales ${compact(sum(r, "sale_amount"))}`, "#b42318"],
			["Gain / (Loss)", gl, "on disposals in period", gl < 0 ? "#e5484d" : "#22a06b"],
			["Draft Assets Value", sum(drafts, "closing_cost"), `${drafts.length} not submitted`, "#f5a524"],
			["Variance vs System", varN, varN ? "assets need review" : "all assets reconcile", varN ? "#e5484d" : "#22a06b", 1],
		];
		ref("kpis").innerHTML = k.map((x) => `<div class="a3-kpi" style="--c:${x[3]}" title="${x[4] ? x[1] : money(x[1])}">
			<div class="l">${x[0]}</div><div class="v">${x[4] ? x[1] : compact(x[1])}</div><div class="s">${x[2]}</div></div>`).join("");
	}

	function groupBy(rows, f) {
		const m = {};
		rows.forEach((r) => {
			const k = r[f] || "(Not Set)";
			m[k] = m[k] || { k, n: 0, cost: 0, dep: 0, nbv: 0 };
			m[k].n++; m[k].cost += r.closing_cost || 0; m[k].dep += r.closing_acc_dep || 0; m[k].nbv += r.closing_nbv || 0;
		});
		return Object.values(m);
	}

	function renderBars() {
		const f = ref("dim").value;
		const g = groupBy(st.rows, f).sort((a, b) => b.cost - a.cost);
		const max = Math.max(1, ...g.map((x) => Math.max(x.cost, x.nbv + x.dep)));
		ref("bars").innerHTML = g.length ? g.map((x) => {
			const w1 = (Math.max(x.nbv, 0) / max) * 100, w2 = (Math.max(x.dep, 0) / max) * 100;
			return `<div class="a3-bar" data-f="${f}" data-v="${esc(x.k)}" title="${esc(x.k)}\nCost: ${money(x.cost)}\nAcc. Dep: ${money(x.dep)}\nNBV: ${money(x.nbv)}\nAssets: ${x.n}">
				<div class="n">${esc(x.k)} <span style="color:var(--a3-muted)">(${x.n})</span></div>
				<div class="t"><i style="width:${w1}%;background:var(--a3-nbv)"></i><i style="width:${w2}%;background:var(--a3-dep)"></i></div>
				<div class="x">${compact(x.cost)}</div></div>`;
		}).join("") : `<div class="a3-empty">No data</div>`;
	}

	function renderDonut() {
		const g = groupBy(st.rows, "status").sort((a, b) => b.n - a.n);
		const total = g.reduce((a, x) => a + x.n, 0);
		const C = 2 * Math.PI * 60;
		let off = 0;
		const segs = g.map((x, i) => {
			const len = total ? (x.n / total) * C : 0;
			const col = STATUS_COLORS[x.k] || PALETTE[i % PALETTE.length];
			const s = `<circle class="seg" data-f="status" data-v="${esc(x.k)}" cx="80" cy="80" r="60" fill="none" stroke="${col}" stroke-width="24"
				stroke-dasharray="${len} ${C - len}" stroke-dashoffset="${-off}" transform="rotate(-90 80 80)"><title>${esc(x.k)}: ${x.n}</title></circle>`;
			off += len; return s;
		}).join("");
		ref("donut").innerHTML = total ? `<svg width="160" height="160" viewBox="0 0 160 160">
				<circle cx="80" cy="80" r="60" fill="none" stroke="var(--a3-soft)" stroke-width="24"/>${segs}
				<text x="80" y="78" text-anchor="middle" font-size="24" font-weight="700" fill="currentColor">${total}</text>
				<text x="80" y="96" text-anchor="middle" font-size="11" fill="var(--a3-muted)">assets</text></svg>
			<div class="a3-dleg">${g.map((x, i) => `<div data-f="status" data-v="${esc(x.k)}"><i style="background:${STATUS_COLORS[x.k] || PALETTE[i % PALETTE.length]}"></i>
				<span>${esc(__(x.k))}</span><span>${x.n}</span></div>`).join("")}</div>`
			: `<div class="a3-empty">No data</div>`;
	}

	function renderRF() {
		const r = st.rows;
		const line = (l, v, cls) => `<tr><td>${l}</td><td class="${cls || ""}">${money(v)}</td></tr>`;
		const tot = (l, v) => `<tr class="tot"><td>${l}</td><td>${money(v)}</td></tr>`;
		ref("rf_cost").innerHTML = `<table class="a3-rf">
			${line("Opening Cost", sum(r, "opening_cost"))}
			${line("+ Additions", sum(r, "additions"), "a3-pos")}
			${line("+ Capitalized Repairs", sum(r, "cap_repairs"), "a3-pos")}
			${line("− Disposals", -sum(r, "disposal_cost"), "a3-neg")}
			${tot("Closing Cost", sum(r, "closing_cost"))}</table>`;
		ref("rf_dep").innerHTML = `<table class="a3-rf">
			${line("Opening Acc. Dep.", sum(r, "opening_acc_dep"))}
			${line("+ Brought In", sum(r, "acc_dep_brought_in"), "a3-pos")}
			${line("+ Depreciation (Period)", sum(r, "dep_period"), "a3-pos")}
			${line("± Value Adjustment", sum(r, "value_adj_period"))}
			${line("− Eliminated on Disposal", -sum(r, "acc_dep_eliminated"), "a3-neg")}
			${tot("Closing Acc. Dep.", sum(r, "closing_acc_dep"))}</table>`;
	}

	function renderYears() {
		const m = {};
		st.rows.forEach((r) => { const y = r.purchase_year || "(Not Set)"; m[y] = (m[y] || 0) + (r.closing_cost || 0) + (r.disposal_cost || 0); });
		const ys = Object.keys(m).sort().slice(-12);
		const max = Math.max(1, ...ys.map((y) => m[y]));
		ref("years").innerHTML = ys.length ? ys.map((y) => `<div class="a3-vb" data-f="purchase_year" data-v="${esc(y)}" title="${y}: ${money(m[y])}">
			<b>${compact(m[y])}</b><i style="height:${(m[y] / max) * 100}%"></i><span>${y}</span></div>`).join("")
			: `<div class="a3-empty" style="width:100%">No data</div>`;
	}

	function cell(r, c) {
		const f = c[0], v = r[f];
		if (c[2]) {
			const cls = (f === "variance" && Math.abs(v || 0) > 0.5) || (f === "gain_loss" && v < 0) ? "a3-neg" : (f === "gain_loss" && v > 0 ? "a3-pos" : "");
			return `<td class="num ${cls}">${v ? format_number(v, null, 2) : "–"}</td>`;
		}
		if (f === "asset") return `<td><a href="/app/asset/${encodeURIComponent(v)}" target="_blank">${esc(v)}</a></td>`;
		if (f === "source_doc" && v) return `<td><a href="/app/${frappe.router.slug(r.source_type)}/${encodeURIComponent(v)}" target="_blank">${esc(v)}</a></td>`;
		if (f === "status") { const col = STATUS_COLORS[v] || "#4f6bed"; return `<td><span class="a3-pill" style="--pc:${col};--pc-bg:${col}1f">${esc(__(v))}</span></td>`; }
		if (f === "purchase_date") return `<td>${dt(v)}</td>`;
		return `<td title="${esc(v)}">${esc(v)}</td>`;
	}

	function renderTable() {
		const rows = st.rows;
		ref("count").textContent = `(${rows.length})`;
		const head = `<thead><tr>${COLS.map((c) => `<th class="${c[2] ? "num" : ""}" data-sort="${c[0]}">${c[1]}${st.sort.f === c[0] ? (st.sort.d > 0 ? " ▲" : " ▼") : ""}</th>`).join("")}</tr></thead>`;
		const body = rows.slice(0, st.limit).map((r) => `<tr>${COLS.map((c) => cell(r, c)).join("")}</tr>`).join("");
		const foot = `<tfoot><tr>${COLS.map((c, i) => i === 0 ? `<td>Total</td>` : c[2] ? `<td class="num">${format_number(sum(rows, c[0]), null, 2)}</td>` : "<td></td>").join("")}</tr></tfoot>`;
		ref("table").innerHTML = rows.length ? head + `<tbody>${body}</tbody>` + foot : `<tbody><tr><td class="a3-empty">No assets match the filters</td></tr></tbody>`;
		ref("more").innerHTML = rows.length > st.limit ? `<button data-act="more">Show more (${rows.length - st.limit} remaining)</button>` : "";
	}

	// ---------- exports ----------
	function exportExcel() {
		if (!st.lastFilters) return;
		const visible = st.rows.map((r) => r.ridx);
		open_url_post(frappe.request.url, {
			cmd: "frappe.desk.query_report.export_query",
			report_name: REPORT,
			file_format_type: "Excel",
			filters: JSON.stringify(st.lastFilters),
			visible_idx: JSON.stringify(visible),
			include_indentation: 0,
		});
	}

	function exportCSV() {
		const head = COLS.map((c) => c[1]);
		const data = [head].concat(st.rows.map((r) => COLS.map((c) => r[c[0]] == null ? "" : r[c[0]])));
		frappe.tools.downloadify(data, null, "Fixed Assets 360");
	}

	function printPDF() {
		const r = st.rows, f = st.lastFilters || {};
		const fl = [];
		Object.keys(ms).forEach((k) => ms[k].values.length && fl.push(`<b>${k.replace(/_/g, " ")}:</b> ${esc(ms[k].values.join(", "))}`));
		Object.keys(st.drill).forEach((k) => fl.push(`<b>${k.replace(/_/g, " ")}:</b> ${esc(st.drill[k])}`));
		if (f.source_type) fl.push(`<b>source:</b> ${esc(f.source_type)}`);
		if (st.search) fl.push(`<b>search:</b> ${esc(st.search)}`);
		const kp = [["Assets", r.length, 1], ["Closing Cost", sum(r, "closing_cost")], ["Acc. Dep.", sum(r, "closing_acc_dep")],
			["NBV", sum(r, "closing_nbv")], ["Dep. (Period)", sum(r, "dep_period")], ["Gain/(Loss)", sum(r, "gain_loss")]];
		const pcols = COLS.filter((c) => !["cost_center", "variance"].includes(c[0]));
		const html = `<!doctype html><html><head><meta charset="utf-8"><title>Fixed Assets 360</title><style>
			@page { size: A4 landscape; margin: 10mm; }
			body { font-family: Inter, Arial, sans-serif; font-size: 9.5px; color: #1f272e; }
			h1 { font-size: 18px; margin: 0; } .sub { color: #6b7280; margin: 2px 0 8px; }
			.flt { background: #f5f6f8; padding: 6px 8px; border-radius: 6px; margin-bottom: 8px; }
			.k { display: flex; gap: 8px; margin-bottom: 10px; } .k div { flex: 1; border: 1px solid #e5e7eb; border-left: 3px solid #4f6bed; border-radius: 6px; padding: 6px 8px; }
			.k small { color: #6b7280; text-transform: uppercase; font-size: 8px; } .k b { display: block; font-size: 13px; margin-top: 2px; }
			.rf { display: flex; gap: 12px; margin-bottom: 10px; } .rf table { flex: 1; border-collapse: collapse; }
			.rf td { padding: 3px 4px; border-bottom: 1px dashed #ddd; } .rf td:last-child { text-align: right; } .rf tr:last-child td { font-weight: 700; border-top: 1.5px solid #000; }
			table.t { width: 100%; border-collapse: collapse; } .t th { background: #f0f2f5; text-align: left; padding: 5px 4px; font-size: 8.5px; text-transform: uppercase; }
			.t td { padding: 4px; border-bottom: 1px solid #eee; } .num { text-align: right; } .t tfoot td { font-weight: 700; border-top: 1.5px solid #000; background: #f7f7f7; }
			thead { display: table-header-group; } tr { page-break-inside: avoid; }
			.foot { margin-top: 8px; color: #9ca3af; font-size: 8px; }</style></head><body>
			<h1>Fixed Asset Register</h1>
			<div class="sub">${esc(f.company)} · Period ${dt(f.from_date)} → ${dt(f.to_date)} · Currency ${esc(st.currency)}</div>
			${fl.length ? `<div class="flt">${fl.join(" &nbsp;·&nbsp; ")}</div>` : ""}
			<div class="k">${kp.map((x) => `<div><small>${x[0]}</small><b>${x[2] ? x[1] : format_number(x[1], null, 2)}</b></div>`).join("")}</div>
			<div class="rf">${ref("rf_cost").innerHTML}${ref("rf_dep").innerHTML}</div>
			<table class="t"><thead><tr>${pcols.map((c) => `<th class="${c[2] ? "num" : ""}">${c[1]}</th>`).join("")}</tr></thead>
			<tbody>${r.map((x) => `<tr>${pcols.map((c) => c[2] ? `<td class="num">${x[c[0]] ? format_number(x[c[0]], null, 2) : "–"}</td>`
				: `<td>${c[0] === "purchase_date" ? dt(x[c[0]]) : esc(x[c[0]])}</td>`).join("")}</tr>`).join("")}</tbody>
			<tfoot><tr>${pcols.map((c, i) => i === 0 ? `<td>Total (${r.length})</td>` : c[2] ? `<td class="num">${format_number(sum(r, c[0]), null, 2)}</td>` : "<td></td>").join("")}</tr></tfoot></table>
			<div class="foot">Printed by ${esc(frappe.session.user_fullname || frappe.session.user)} on ${frappe.datetime.now_datetime()}</div>
			<script>window.onload = function(){ setTimeout(function(){ window.print(); }, 300); };<\/script></body></html>`;
		const w = window.open("", "_blank");
		if (!w) { frappe.msgprint(__("Please allow pop-ups to print")); return; }
		w.document.open(); w.document.write(html); w.document.close();
	}

	// ---------- events ----------
	R.addEventListener("click", (e) => {
		const t = e.target.closest("[data-act],[data-f][data-v],[data-sort],.a3-chip");
		if (!t) return;
		if (t.classList.contains("a3-chip")) {
			if (t.dataset.k === "*") st.drill = {}; else delete st.drill[t.dataset.k];
			st.limit = 150; return render();
		}
		if (t.dataset.sort) {
			const f = t.dataset.sort;
			st.sort = { f, d: st.sort.f === f ? -st.sort.d : (COLS.find((c) => c[0] === f)[2] ? -1 : 1) };
			applyLocal(); return renderTable();
		}
		if (t.dataset.v !== undefined && t.dataset.f) {
			const f = t.dataset.f, v = t.dataset.v;
			if (st.drill[f] === v) delete st.drill[f]; else st.drill[f] = v;
			st.limit = 150; return render();
		}
		const a = t.dataset.act;
		if (a === "run") { st.drill = {}; run(); }
		else if (a === "reset") { setDefaults(); run(); }
		else if (a === "more") { st.limit += 300; renderTable(); }
		else if (a === "excel") exportExcel();
		else if (a === "csv") exportCSV();
		else if (a === "pdf") printPDF();
		else if (a === "report") frappe.set_route("query-report", REPORT, st.lastFilters || {});
	});
	ref("dim").addEventListener("change", renderBars);
	let tmr;
	const searchEl = ref("search");
	searchEl.addEventListener("input", () => { const v = (searchEl.value || "").trim(); clearTimeout(tmr); tmr = setTimeout(() => { st.search = v; st.limit = 150; render(); }, 250); });
	fe("company").addEventListener("change", () => { ms.cost_center.options = null; ms.cost_center.set([]); });

	init();
})();

style:
:host { display: block; }
.a3 {
  --a3-blue: #4f6bed; --a3-nbv: #22a06b; --a3-dep: #e5484d; --a3-amber: #f5a524; --a3-violet: #8e4ec6;
  --a3-bg: var(--card-bg, #fff); --a3-soft: var(--subtle-fg, #f7f8fa); --a3-border: var(--border-color, #e6e8eb);
  --a3-text: var(--text-color, #1f272e); --a3-muted: var(--text-muted, #7c8a96);
  font-family: var(--font-stack, Inter, system-ui, sans-serif); color: var(--a3-text); font-size: 13px;
}
.a3 * { box-sizing: border-box; }
.a3-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; flex-wrap: wrap; margin-bottom: 12px; }
.a3-title { font-size: 20px; font-weight: 700; letter-spacing: -.2px; }
.a3-sub { color: var(--a3-muted); margin-top: 2px; }
.a3-actions, .a3-fbtns { display: flex; gap: 6px; flex-wrap: wrap; }
.a3-btn { border: 1px solid var(--a3-border); background: var(--a3-bg); color: var(--a3-text); border-radius: 8px;
  padding: 6px 12px; font-size: 12.5px; font-weight: 500; cursor: pointer; transition: .15s; }
.a3-btn:hover { background: var(--a3-soft); }
.a3-primary { background: var(--a3-blue); border-color: var(--a3-blue); color: #fff; }
.a3-primary:hover { background: #3d57d6; }
.a3-green { background: #1f8f5f; border-color: #1f8f5f; color: #fff; }
.a3-green:hover { background: #187a50; }
.a3-dark { background: #262b33; border-color: #262b33; color: #fff; }
.a3-dark:hover { background: #111; }

.a3-filters { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 10px; align-items: end;
  background: var(--a3-bg); border: 1px solid var(--a3-border); border-radius: 12px; padding: 12px; }
.a3-f { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.a3-f > span { font-size: 11px; color: var(--a3-muted); font-weight: 600; text-transform: uppercase; letter-spacing: .4px; }
.a3-f select, .a3-f input, .a3-search, .a3-card-h select {
  width: 100%; border: 1px solid var(--a3-border); background: var(--control-bg, var(--a3-soft)); color: var(--a3-text);
  border-radius: 8px; padding: 6px 8px; font-size: 12.5px; outline: none; height: 32px; }
.a3-f select:focus, .a3-f input:focus, .a3-search:focus { border-color: var(--a3-blue); }
.a3-chk { display: flex; align-items: center; gap: 6px; font-size: 12px; color: var(--a3-muted); height: 32px; cursor: pointer; }

.a3-ms { position: relative; }
.a3-ms-btn { width: 100%; height: 32px; text-align: start; border: 1px solid var(--a3-border); background: var(--control-bg, var(--a3-soft));
  border-radius: 8px; padding: 6px 26px 6px 8px; font-size: 12.5px; cursor: pointer; color: var(--a3-text);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; position: relative; }
.a3-ms-btn::after { content: "▾"; position: absolute; inset-inline-end: 9px; color: var(--a3-muted); }
.a3-ms-btn.on { border-color: var(--a3-blue); color: var(--a3-blue); font-weight: 600; }
.a3-ms-pop { display: none; position: absolute; z-index: 50; top: 36px; inset-inline-start: 0; width: 260px; max-height: 300px;
  background: var(--a3-bg); border: 1px solid var(--a3-border); border-radius: 10px; box-shadow: 0 10px 30px rgba(0,0,0,.12); padding: 8px; }
.a3-ms.open .a3-ms-pop { display: flex; flex-direction: column; }
.a3-ms-pop input[type=text] { height: 30px; border: 1px solid var(--a3-border); border-radius: 6px; padding: 4px 8px; margin-bottom: 6px; background: var(--a3-soft); color: var(--a3-text); }
.a3-ms-list { overflow: auto; flex: 1; }
.a3-ms-list label { display: flex; gap: 8px; align-items: center; padding: 5px 6px; border-radius: 6px; cursor: pointer; font-size: 12.5px; }
.a3-ms-list label:hover { background: var(--a3-soft); }
.a3-ms-foot { display: flex; justify-content: space-between; border-top: 1px solid var(--a3-border); padding-top: 6px; margin-top: 6px; }
.a3-ms-foot a { color: var(--a3-blue); cursor: pointer; font-size: 12px; }

.a3-chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 10px 0 0; }
.a3-chip { background: #eef1ff; color: var(--a3-blue); border-radius: 20px; padding: 3px 10px; font-size: 12px; font-weight: 600; cursor: pointer; }
.a3-chip b { margin-inline-start: 6px; }

.a3-loading { display: none; align-items: center; gap: 10px; padding: 30px; justify-content: center; color: var(--a3-muted); }
.a3.busy .a3-loading { display: flex; }
.a3.busy .a3-body { opacity: .35; pointer-events: none; }
.a3-spin { width: 18px; height: 18px; border: 2px solid var(--a3-border); border-top-color: var(--a3-blue); border-radius: 50%; animation: a3s .8s linear infinite; }
@keyframes a3s { to { transform: rotate(360deg); } }

.a3-kpis { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; margin: 12px 0; }
.a3-kpi { background: var(--a3-bg); border: 1px solid var(--a3-border); border-radius: 12px; padding: 12px 14px; position: relative; overflow: hidden; }
.a3-kpi::before { content: ""; position: absolute; inset-inline-start: 0; top: 0; bottom: 0; width: 4px; background: var(--c, var(--a3-blue)); }
.a3-kpi .l { font-size: 11px; color: var(--a3-muted); font-weight: 600; text-transform: uppercase; letter-spacing: .4px; }
.a3-kpi .v { font-size: 20px; font-weight: 700; margin-top: 4px; font-variant-numeric: tabular-nums; }
.a3-kpi .s { font-size: 11.5px; color: var(--a3-muted); margin-top: 2px; }

.a3-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 10px; }
@media (max-width: 1100px) { .a3-kpis { grid-template-columns: repeat(2, 1fr); } .a3-grid { grid-template-columns: 1fr; } .a3-span2 { grid-column: auto !important; } }
.a3-span2 { grid-column: span 2; }
.a3-card { background: var(--a3-bg); border: 1px solid var(--a3-border); border-radius: 12px; padding: 12px 14px; margin-bottom: 10px; min-width: 0; }
.a3-grid .a3-card { margin-bottom: 0; }
.a3-card-h { display: flex; align-items: center; gap: 8px; font-weight: 600; margin-bottom: 10px; flex-wrap: wrap; }
.a3-card-h select { width: auto; height: 28px; }
.a3-legend { margin-inline-start: auto; font-weight: 400; font-size: 11.5px; color: var(--a3-muted); display: flex; align-items: center; gap: 4px; }
.a3-legend i { width: 10px; height: 10px; border-radius: 3px; display: inline-block; margin-inline-start: 8px; }

.a3-bars { display: flex; flex-direction: column; gap: 7px; max-height: 340px; overflow: auto; }
.a3-bar { display: grid; grid-template-columns: 150px 1fr 110px; gap: 10px; align-items: center; cursor: pointer; padding: 2px 4px; border-radius: 6px; }
.a3-bar:hover { background: var(--a3-soft); }
.a3-bar .n { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12.5px; }
.a3-bar .t { height: 14px; background: var(--a3-soft); border-radius: 4px; display: flex; overflow: hidden; }
.a3-bar .t i { display: block; height: 100%; }
.a3-bar .x { text-align: end; font-variant-numeric: tabular-nums; font-size: 12px; font-weight: 600; }

.a3-donut { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.a3-donut svg path, .a3-donut svg circle.seg { cursor: pointer; transition: opacity .15s; }
.a3-donut svg circle.seg:hover { opacity: .75; }
.a3-dleg { width: 100%; display: flex; flex-direction: column; gap: 3px; }
.a3-dleg div { display: flex; align-items: center; gap: 8px; cursor: pointer; padding: 3px 6px; border-radius: 6px; font-size: 12.5px; }
.a3-dleg div:hover { background: var(--a3-soft); }
.a3-dleg i { width: 10px; height: 10px; border-radius: 50%; }
.a3-dleg span:last-child { margin-inline-start: auto; font-weight: 600; }

.a3-rf { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.a3-rf td { padding: 6px 4px; border-bottom: 1px dashed var(--a3-border); }
.a3-rf td:last-child { text-align: end; font-weight: 600; }
.a3-rf tr.tot td { border-top: 2px solid var(--a3-text); border-bottom: none; font-weight: 700; font-size: 14px; }
.a3-pos { color: var(--a3-nbv); } .a3-neg { color: var(--a3-dep); }

.a3-vbars { display: flex; align-items: flex-end; gap: 6px; height: 190px; padding-top: 14px; overflow-x: auto; }
.a3-vb { flex: 1; min-width: 26px; display: flex; flex-direction: column; align-items: center; gap: 4px; height: 100%; justify-content: flex-end; cursor: pointer; }
.a3-vb i { width: 100%; background: linear-gradient(180deg, #7b8ff5, var(--a3-blue)); border-radius: 5px 5px 2px 2px; min-height: 2px; }
.a3-vb:hover i { filter: brightness(1.1); }
.a3-vb span { font-size: 10.5px; color: var(--a3-muted); }
.a3-vb b { font-size: 10px; }

.a3-search { max-width: 340px; margin-inline-start: auto; }
.a3-table-wrap { overflow: auto; max-height: 560px; border: 1px solid var(--a3-border); border-radius: 8px; }
.a3-table { width: 100%; border-collapse: collapse; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.a3-table th { position: sticky; top: 0; background: var(--a3-soft); text-align: start; padding: 8px; font-size: 11px; text-transform: uppercase;
  letter-spacing: .3px; color: var(--a3-muted); cursor: pointer; white-space: nowrap; border-bottom: 1px solid var(--a3-border); z-index: 1; }
.a3-table th.num, .a3-table td.num { text-align: end; }
.a3-table td { padding: 7px 8px; border-bottom: 1px solid var(--a3-border); white-space: nowrap; max-width: 260px; overflow: hidden; text-overflow: ellipsis; }
.a3-table tbody tr:hover { background: var(--a3-soft); }
.a3-table tfoot td { position: sticky; bottom: 0; background: var(--a3-soft); font-weight: 700; border-top: 2px solid var(--a3-border); }
.a3-table a { color: var(--a3-blue); text-decoration: none; font-weight: 500; }
.a3-pill { padding: 2px 8px; border-radius: 20px; font-size: 11px; font-weight: 600; background: var(--pc-bg, #eef1ff); color: var(--pc, var(--a3-blue)); }
.a3-more { text-align: center; padding: 8px; }
.a3-more button { border: none; background: none; color: var(--a3-blue); cursor: pointer; font-weight: 600; }
.a3-empty { padding: 30px; text-align: center; color: var(--a3-muted); }
